// script.js - Bespoke Interactivity for Velvet & Crumb Artisan Roasters
document.addEventListener('DOMContentLoaded', () => {
  // Theme Toggle
  const themeToggleBtn = document.getElementById('themeToggleBtn');
  const htmlRoot = document.documentElement;

  themeToggleBtn?.addEventListener('click', () => {
    const currentTheme = htmlRoot.getAttribute('data-theme') || 'light';
    const nextTheme = currentTheme === 'light' ? 'dark' : 'light';
    htmlRoot.setAttribute('data-theme', nextTheme);
  });

  // Mobile Drawer
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const mobileDrawer = document.getElementById('mobileDrawer');
  const closeDrawerBtn = document.getElementById('closeDrawerBtn');

  mobileToggle?.addEventListener('click', () => mobileDrawer?.classList.add('open'));
  closeDrawerBtn?.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  document.querySelectorAll('.drawer-link').forEach(link => {
    link.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  });

  // Toast Notification System
  function showToast(message) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    container.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s';
      setTimeout(() => toast.remove(), 300);
    }, 3200);
  }
  window.showToast = showToast;

  // Contact Modal
  const modalBackdrop = document.getElementById('contactModalBackdrop');
  const openModalBtn = document.getElementById('openContactModalBtn');
  const drawerContactBtn = document.getElementById('drawerContactBtn');
  const closeModalBtn = document.getElementById('closeContactModalBtn');
  const contactForm = document.getElementById('contactIntakeForm');

  function openModal() {
    modalBackdrop?.classList.add('open');
    mobileDrawer?.classList.remove('open');
  }
  function closeModal() {
    modalBackdrop?.classList.remove('open');
  }

  openModalBtn?.addEventListener('click', openModal);
  drawerContactBtn?.addEventListener('click', openModal);
  closeModalBtn?.addEventListener('click', closeModal);
  modalBackdrop?.addEventListener('click', (e) => {
    if (e.target === modalBackdrop) closeModal();
  });

  contactForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = document.getElementById('contactName').value;
    closeModal();
    showToast('✨ Thank you, ' + name + '! Your inquiry was submitted.');
    contactForm.reset();
  });

  // FAQ Accordion
  document.querySelectorAll('.faq-question').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !isExpanded);
      item.classList.toggle('active');
    });
  });


      // Universal Estimator Logic
      let currentRate = 1;
      let currentTierName = 'Essential';
      const tierPills = document.querySelectorAll('.tier-pill');
      const scopeSlider = document.getElementById('scopeSlider');
      const velocitySelect = document.getElementById('velocitySelect');

      function updateEstimator() {
        const units = parseInt(scopeSlider?.value || 3);
        document.getElementById('scopeUnitsVal').textContent = units;

        let velocityMultiplier = 1;
        let days = 14;
        const vel = velocitySelect?.value || 'standard';
        if (vel === 'express') {
          velocityMultiplier = 1.35;
          days = 6;
        } else if (vel === 'instant') {
          velocityMultiplier = 1.75;
          days = 3;
        }

        const basePrice = 850;
        const total = Math.round(basePrice * currentRate * units * velocityMultiplier);

        document.getElementById('calcTotalCost').textContent = '$' + total.toLocaleString();
        document.getElementById('selectedTierLabel').textContent = currentTierName;
        document.getElementById('turnaroundLabel').textContent = days + ' Business Days';
      }

      tierPills.forEach(pill => {
        pill.addEventListener('click', () => {
          tierPills.forEach(p => p.classList.remove('active'));
          pill.classList.add('active');
          currentRate = parseFloat(pill.getAttribute('data-rate'));
          currentTierName = pill.textContent.trim();
          updateEstimator();
        });
      });

      scopeSlider?.addEventListener('input', updateEstimator);
      velocitySelect?.addEventListener('change', updateEstimator);
      updateEstimator();

      document.getElementById('claimQuoteBtn')?.addEventListener('click', () => {
        showToast('✨ Proposal locked! Our director will deliver your formal intake packet within 2 hours.');
      });

});

css:
:root {
    --primary: #1A1A1A;
    --accent: #FF4D00;
    --accent-hover: #E64500;
    --bg: #FFFFFF;
    --surface: #F5F5F7;
    --text: #1A1A1A;
    --text-muted: #666666;
    --border: #E5E5E5;
    --glass: rgba(255, 255, 255, 0.8);
    --container-width: 1280px;
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg);
    color: var(--text);
    line-height: 1.6;
    overflow-x: hidden;
}

h1, h2, h3, h4 {
    font-family: 'Space Grotesk', sans-serif;
    font-weight: 700;
    line-height: 1.1;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.section {
    padding: 8rem 0;
}

.badge {
    display: inline-block;
    padding: 0.5rem 1rem;
    background: var(--accent);
    color: white;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 1.5rem;
}

/* Header */
.site-header {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1000;
    background: var(--glass);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border);
}

nav.container {
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: -0.02em;
}

.logo span {
    color: var(--accent);
}

.nav-links {
    display: flex;
    gap: 2.5rem;
}

.nav-links a {
    font-weight: 500;
    font-size: 0.95rem;
}

.nav-links a:hover {
    color: var(--accent);
}

.nav-actions {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    position: relative;
    color: var(--text);
    transition: var(--transition);
}

.icon-btn:hover {
    color: var(--accent);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background: var(--accent);
    color: white;
    font-size: 0.65rem;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
}

/* Hero */
.hero {
    height: 100vh;
    position: relative;
    display: flex;
    align-items: center;
    overflow: hidden;
}

.hero-bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
}

.hero-bg img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: brightness(0.9);
}

.hero-text {
    max-width: 600px;
    color: white;
}

.hero-text h1 {
    font-size: clamp(3rem, 8vw, 5rem);
    margin-bottom: 1.5rem;
}

.hero-text p {
    font-size: 1.25rem;
    margin-bottom: 2.5rem;
    opacity: 0.9;
}

.hero-btns {
    display: flex;
    gap: 1.5rem;
}

.btn {
    display: inline-block;
    padding: 1.2rem 2.5rem;
    font-weight: 600;
    border-radius: 4px;
    cursor: pointer;
    border: none;
    transition: var(--transition);
    text-align: center;
}

.btn-primary {
    background: var(--accent);
    color: white;
}

.btn-primary:hover {
    background: var(--accent-hover);
    transform: translateY(-2px);
}

.btn-secondary {
    background: white;
    color: var(--text);
}

.btn-secondary:hover {
    background: #f0f0f0;
    transform: translateY(-2px);
}

/* Product Grid */
.section-header {
    margin-bottom: 4rem;
    text-align: center;
}

.section-header h2 {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--surface);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
}

.product-img {
    position: relative;
    height: 400px;
    overflow: hidden;
}

.product-img img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.6s ease;
}

.hover-img {
    position: absolute;
    top: 0;
    left: 0;
    opacity: 0;
}

.product-card:hover .primary-img {
    opacity: 0;
}

.product-card:hover .hover-img {
    opacity: 1;
    transform: scale(1.05);
}

.add-to-cart {
    position: absolute;
    bottom: 1.5rem;
    left: 50%;
    transform: translateX(-50%) translateY(20px);
    padding: 0.8rem 2rem;
    background: var(--primary);
    color: white;
    border: none;
    font-weight: 600;
    opacity: 0;
    transition: var(--transition);
    cursor: pointer;
    width: 80%;
}

.product-card:hover .add-to-cart {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
}

.product-info {
    padding: 1.5rem;
    text-align: center;
}

.product-info h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.price {
    color: var(--accent);
    font-weight: 700;
}

/* Tech Section */
.tech-layout {
    display: grid;
    grid-template-columns: 1.2fr 0.8fr;
    gap: 4rem;
    align-items: center;
}

.tech-visual {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
}

.tech-visual img {
    width: 100%;
    display: block;
}

.hotspot {
    position: absolute;
    width: 24px;
    height: 24px;
    background: var(--accent);
    border: 4px solid white;
    border-radius: 50%;
    cursor: pointer;
    box-shadow: 0 0 20px rgba(255, 77, 0, 0.4);
    transition: var(--transition);
}

.hotspot:hover {
    transform: scale(1.3);
}

.hotspot::after {
    content: attr(data-content);
    position: absolute;
    bottom: 35px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--primary);
    color: white;
    padding: 0.8rem 1.2rem;
    border-radius: 4px;
    font-size: 0.85rem;
    width: 200px;
    text-align: center;
    opacity: 0;
    pointer-events: none;
    transition: var(--transition);
}

.hotspot:hover::after {
    opacity: 1;
    bottom: 40px;
}

.accordion-item {
    border-bottom: 1px solid var(--border);
    margin-bottom: 1rem;
}

.accordion-trigger {
    width: 100%;
    text-align: left;
    padding: 1.5rem 0;
    background: none;
    border: none;
    font-family: 'Space Grotesk', sans-serif;
    font-size: 1.2rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.accordion-trigger::after {
    content: '+';
    font-size: 1.5rem;
}

.accordion-item.active .accordion-trigger::after {
    content: '-';
}

.accordion-panel {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease-out;
    color: var(--text-muted);
}

.accordion-item.active .accordion-panel {
    max-height: 200px;
    padding-bottom: 1.5rem;
}

/* Customizer */
.customizer-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    background: var(--surface);
    padding: 3rem;
    border-radius: 12px;
}

.custom-preview {
    position: relative;
    background: white;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.custom-preview img {
    width: 100%;
    mix-blend-mode: multiply;
}

.color-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: var(--accent);
    mix-blend-mode: overlay;
    opacity: 0.4;
    pointer-events: none;
}

.control-group {
    margin-bottom: 2.5rem;
}

.control-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 1rem;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 0.1em;
}

.swatches {
    display: flex;
    gap: 1rem;
}

.swatch {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: 2px solid transparent;
    cursor: pointer;
    transition: var(--transition);
}

.swatch.active {
    border-color: var(--primary);
    transform: scale(1.1);
}

select {
    width: 100%;
    padding: 1rem;
    border: 1px solid var(--border);
    border-radius: 4px;
    font-family: inherit;
    outline: none;
}

.custom-summary {
    padding-top: 2rem;
    border-top: 1px solid var(--border);
}

.full-width {
    width: 100%;
    margin-top: 1.5rem;
}

/* Style Edit */
.style-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
}

.style-item {
    aspect-ratio: 1/1;
    overflow: hidden;
    border-radius: 4px;
}

.style-item img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.style-item:hover img {
    transform: scale(1.1);
}

/* Newsletter */
.newsletter-card {
    background: var(--primary);
    color: white;
    padding: 5rem 3rem;
    border-radius: 12px;
    text-align: center;
    max-width: 900px;
    margin: 0 auto;
}

.newsletter-card h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.newsletter-card p {
    margin-bottom: 2.5rem;
    opacity: 0.8;
}

.newsletter-form {
    display: flex;
    gap: 1rem;
    max-width: 500px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    padding: 1.2rem;
    border: none;
    border-radius: 4px;
    outline: none;
}

/* Footer */
.site-footer {
    padding: 6rem 0 2rem;
    background: var(--surface);
    border-top: 1px solid var(--border);
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-info h3 {
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
}

.footer-info p {
    color: var(--text-muted);
    max-width: 300px;
}

.footer-links h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 0.1em;
}

.footer-links ul li {
    margin-bottom: 0.8rem;
}

.footer-links ul li a {
    color: var(--text-muted);
}

.footer-links ul li a:hover {
    color: var(--accent);
}

.social-icons {
    display: flex;
    gap: 1rem;
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border);
    text-align: center;
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Interactive UI Elements */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: var(--primary);
    color: white;
    padding: 1rem 2rem;
    border-radius: 4px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.2);
    transform: translateY(100px);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    z-index: 2000;
}

.toast.show {
    transform: translateY(0);
}

.mobile-nav {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: white;
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
    transform: translateX(100%);
    transition: transform 0.5s ease;
}

.mobile-nav.active {
    transform: translateX(0);
}

.mobile-nav-links {
    text-align: center;
}

.mobile-nav-links li {
    margin-bottom: 2rem;
}

.mobile-nav-links a {
    font-size: 2rem;
    font-family: 'Space Grotesk', sans-serif;
    font-weight: 700;
}

.mobile-menu-toggle {
    display: none;
    flex-direction: column;
    gap: 6px;
    background: none;
    border: none;
    cursor: pointer;
}

.mobile-menu-toggle span {
    width: 25px;
    height: 2px;
    background: var(--text);
    transition: var(--transition);
}

@media (max-width: 992px) {
    .tech-layout, .customizer-container {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
        gap: 2rem;
    }

    .style-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .mobile-menu-toggle {
        display: flex;
    }

    .section {
        padding: 4rem 0;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .hero-btns {
        flex-direction: column;
    }
}

