document.addEventListener('DOMContentLoaded', () => {
    // Cart Logic
    let cartCountValue = 0;
    const cartCountElement = document.querySelector('.cart-count');
    const toast = document.getElementById('toast');
    const addButtons = document.querySelectorAll('.add-to-cart, .btn-primary.full-width');

    const showToast = (message = 'Added to cart!') => {
        toast.textContent = message;
        toast.classList.add('show');
        setTimeout(() => {
            toast.classList.remove('show');
        }, 3000);
    };

    addButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            cartCountValue++;
            cartCountElement.textContent = cartCountValue;
            cartCountElement.style.transform = 'scale(1.2)';
            setTimeout(() => cartCountElement.style.transform = 'scale(1)', 200);
            showToast();
        });
    });

    // Mobile Menu Toggle
    const menuToggle = document.querySelector('.mobile-menu-toggle');
    const mobileNav = document.querySelector('.mobile-nav');
    const mobileLinks = document.querySelectorAll('.mobile-nav-links a');

    menuToggle.addEventListener('click', () => {
        mobileNav.classList.toggle('active');
        menuToggle.classList.toggle('open');
        if (mobileNav.classList.contains('active')) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'auto';
        }
    });

    mobileLinks.forEach(link => {
        link.addEventListener('click', () => {
            mobileNav.classList.remove('active');
            document.body.style.overflow = 'auto';
        });
    });

    // Accordion Logic
    const accordionItems = document.querySelectorAll('.accordion-item');

    accordionItems.forEach(item => {
        const trigger = item.querySelector('.accordion-trigger');
        trigger.addEventListener('click', () => {
            const isActive = item.classList.contains('active');

            // Close all items
            accordionItems.forEach(i => i.classList.remove('active'));

            // Toggle current item
            if (!isActive) {
                item.classList.add('active');
            }
        });
    });

    // Visual Customizer Logic
    const swatches = document.querySelectorAll('.swatch');
    const shoeOverlay = document.getElementById('shoe-overlay');
    const materialSelect = document.getElementById('material-select');
    const customShoeImg = document.getElementById('custom-shoe-img');

    swatches.forEach(swatch => {
        swatch.addEventListener('click', () => {
            // Update active state
            swatches.forEach(s => s.classList.remove('active'));
            swatch.classList.add('active');

            // Apply color
            const color = swatch.getAttribute('data-color');
            shoeOverlay.style.backgroundColor = color;

            // Animation effect
            customShoeImg.style.transform = 'scale(0.98)';
            setTimeout(() => customShoeImg.style.transform = 'scale(1)', 150);
        });
    });

    materialSelect.addEventListener('change', (e) => {
        const val = e.target.value;
        if (val === 'matte') {
            customShoeImg.style.filter = 'contrast(1) brightness(1)';
            shoeOverlay.style.mixBlendMode = 'overlay';
        } else if (val === 'glossy') {
            customShoeImg.style.filter = 'contrast(1.2) brightness(1.1)';
            shoeOverlay.style.mixBlendMode = 'color-burn';
        } else {
            customShoeImg.style.filter = 'sepia(0.2) contrast(0.9)';
            shoeOverlay.style.mixBlendMode = 'soft-light';
        }
    });

    // Newsletter Form Validation
    const newsletterForm = document.getElementById('newsletter-form');
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const emailInput = newsletterForm.querySelector('input');
        if (emailInput.value) {
            showToast('Welcome to the inner circle!');
            emailInput.value = '';
        }
    });

    // Sticky Header Effect
    window.addEventListener('scroll', () => {
        const header = document.querySelector('.site-header');
        if (window.scrollY > 50) {
            header.style.padding = '0.5rem 0';
            header.style.boxShadow = '0 10px 30px rgba(0,0,0,0.05)';
        } else {
            header.style.padding = '1rem 0';
            header.style.boxShadow = 'none';
        }
    });

    // Hotspot Scroll Animation
    const hotspots = document.querySelectorAll('.hotspot');
    const observerOptions = {
        threshold: 0.5
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.opacity = '1';
                entry.target.style.transform = 'scale(1)';
            }
        });
    }, observerOptions);

    hotspots.forEach(hotspot => {
        hotspot.style.opacity = '0';
        hotspot.style.transform = 'scale(0)';
        observer.observe(hotspot);
    });
});

