/* styles.css - Bespoke Design System for AquaVibe Marine & Aquatics */
:root {
  --bg-app: #f8fafc;
  --bg-surface: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-secondary: #475569;
  --border-subtle: #e2e8f0;
  --primary: #003366;
  --primary-hover: #1e293b;
  --accent: #06b6d4;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 6px 18px rgba(0,0,0,0.08);
  --shadow-lg: 0 16px 36px rgba(0,0,0,0.12);
  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
}

[data-theme="dark"] {
  --bg-app: #0b1120;
  --bg-surface: #131d31;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-secondary: #cbd5e1;
  --border-subtle: #1e293b;
  --primary: #ffffff;
  --primary-hover: #f1f5f9;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-md: 0 6px 18px rgba(0,0,0,0.5);
  --shadow-lg: 0 16px 36px rgba(0,0,0,0.6);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background: var(--bg-app);
  color: var(--text-main);
  line-height: 1.6;
  overflow-x: hidden;
  transition: background 0.3s ease, color 0.3s ease;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-subtle);
  z-index: 100;
}
[data-theme="dark"] .site-header {
  background: rgba(19, 29, 49, 0.88);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
  color: var(--text-main);
  font-family: var(--font-heading);
  font-size: 1.3rem;
  letter-spacing: -0.02em;
}

.logo-symbol {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
}
[data-theme="dark"] .logo-symbol {
  color: #0f172a;
}

.main-nav {
  display: flex;
  gap: 1.75rem;
}

.nav-link {
  text-decoration: none;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.95rem;
  transition: color 0.2s;
}
.nav-link:hover {
  color: var(--accent);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.icon-btn {
  background: none;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  padding: 0.5rem;
  cursor: pointer;
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.icon-btn:hover {
  background: var(--border-subtle);
  transform: translateY(-1px);
}

.sun-icon { display: none; }
.moon-icon { display: block; }
[data-theme="dark"] .sun-icon { display: block; }
[data-theme="dark"] .moon-icon { display: none; }

.hamburger-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}
.hamburger-btn .bar {
  width: 22px;
  height: 2px;
  background: var(--text-main);
  border-radius: 2px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.75rem 1.4rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  text-decoration: none;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}
.btn-primary {
  background: var(--accent);
  color: #ffffff;
}
.btn-primary:hover {
  filter: brightness(1.1);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(0,0,0,0.15);
}
.btn-outline {
  border-color: var(--border-subtle);
  background: var(--bg-surface);
  color: var(--text-main);
}
.btn-outline:hover {
  border-color: var(--text-main);
  background: var(--border-subtle);
}
.btn-lg {
  padding: 0.95rem 1.85rem;
  font-size: 1.05rem;
}
.btn-block {
  width: 100%;
}

/* Hero */
.hero-section {
  padding: 5rem 0;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  align-items: center;
  gap: 3.5rem;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.95rem;
  background: var(--border-subtle);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1.5rem;
}
.pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.3);
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2.4rem, 4.2vw, 3.8rem);
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 1.25rem;
}
.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 520px;
  margin-bottom: 2rem;
}

.hero-cta-group {
  display: flex;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.hero-metrics {
  display: flex;
  gap: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-subtle);
}
.metric-num {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-main);
}
.metric-lbl {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.visual-frame {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border-subtle);
}
.hero-img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.visual-frame:hover .hero-img {
  transform: scale(1.04);
}
.floating-badge {
  position: absolute;
  bottom: 1.5rem;
  left: 1.5rem;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(8px);
  color: #fff;
  padding: 0.45rem 0.9rem;
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
}

/* Interactive Section */
.interactive-section {
  padding: 5rem 0;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}
.section-head {
  margin-bottom: 3rem;
}
.text-center {
  text-align: center;
}
.eyebrow {
  display: inline-block;
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 0.5rem;
}
.section-head h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 3.2vw, 2.5rem);
  letter-spacing: -0.02em;
}
.section-sub {
  color: var(--text-muted);
  max-width: 600px;
  margin: 0.5rem auto 0;
}

.widget-interactive-box {
  background: var(--bg-app);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  box-shadow: var(--shadow-md);
  max-width: 960px;
  margin: 0 auto;
}

.calculator-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 2.5rem;
}

.calc-input-pane h3 {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  margin-bottom: 0.35rem;
}
.calc-input-pane p {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.input-field {
  margin-bottom: 1.25rem;
}
.input-field label {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
  color: var(--text-main);
}
.slider-input {
  width: 100%;
  accent-color: var(--accent);
  cursor: pointer;
}
.select-input {
  width: 100%;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-family: inherit;
  font-weight: 500;
}

.pill-selector {
  display: flex;
  gap: 0.5rem;
}
.tier-pill {
  flex: 1;
  padding: 0.6rem;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
}
.tier-pill.active {
  background: var(--text-main);
  color: var(--bg-surface);
  border-color: var(--text-main);
}

.calc-output-pane {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: var(--shadow-sm);
}

.result-card {
  text-align: center;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border-subtle);
}
.result-label {
  font-size: 0.82rem;
  color: var(--text-muted);
  display: block;
  margin-bottom: 0.25rem;
}
.result-number {
  font-family: var(--font-heading);
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--accent);
  display: block;
}
.result-sub {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.result-details {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin: 1.5rem 0;
  font-size: 0.88rem;
}
.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Showcase Grid */
.showcase-section {
  padding: 5rem 0;
}
.showcase-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}
.showcase-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.25s, box-shadow 0.25s;
}
.showcase-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.card-img-wrap {
  height: 220px;
  overflow: hidden;
}
.card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.showcase-card:hover .card-img {
  transform: scale(1.06);
}
.card-body {
  padding: 1.75rem;
}
.card-tag {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
  margin-bottom: 0.4rem;
  display: block;
}
.card-body h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}
.card-body p {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* Testimonials */
.testimonials-section {
  padding: 5rem 0;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
}
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  max-width: 900px;
  margin: 0 auto;
}
.testimonial-card {
  background: var(--bg-app);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 2rem;
}
.star-rating {
  color: #f59e0b;
  margin-bottom: 1rem;
  font-size: 1.1rem;
}
.testimonial-card p {
  font-size: 0.95rem;
  color: var(--text-secondary);
  font-style: italic;
  margin-bottom: 1.25rem;
}
.author-meta strong {
  display: block;
  font-size: 0.95rem;
}
.author-meta span {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* FAQ */
.faq-section {
  padding: 5rem 0;
}
.faq-accordion {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.faq-item {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  text-align: left;
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-arrow {
  font-size: 1.3rem;
  transition: transform 0.25s;
}
.faq-item.active .faq-arrow {
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  padding: 0 1.5rem;
  color: var(--text-muted);
  font-size: 0.92rem;
}
.faq-item.active .faq-answer {
  max-height: 200px;
  padding: 0 1.5rem 1.25rem;
}

/* Modal Dialog */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s;
  padding: 1.5rem;
}
.modal-backdrop.open {
  opacity: 1;
  visibility: visible;
}
.modal-dialog {
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  padding: 2.25rem;
  width: 100%;
  max-width: 500px;
  box-shadow: var(--shadow-lg);
}
.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}
.modal-header h3 {
  font-family: var(--font-heading);
}
.drawer-close-btn {
  background: none;
  border: none;
  font-size: 1.6rem;
  cursor: pointer;
  color: var(--text-main);
}
.form-group {
  margin-bottom: 1.2rem;
}
.form-group label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
}
.form-group input, .form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  background: var(--bg-app);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-family: inherit;
}

/* Mobile Drawer */
.mobile-drawer {
  position: fixed;
  inset: 0;
  background: var(--bg-surface);
  z-index: 1002;
  transform: translateY(-100%);
  transition: transform 0.3s ease;
  padding: 2rem;
  display: flex;
  flex-direction: column;
}
.mobile-drawer.open {
  transform: translateY(0);
}
.drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}
.drawer-links {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  font-size: 1.25rem;
  font-weight: 600;
}
.drawer-link {
  text-decoration: none;
  color: var(--text-main);
}

/* Toast */
.toast-container {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.toast {
  background: var(--text-main);
  color: var(--bg-surface);
  padding: 0.9rem 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.9rem;
  font-weight: 500;
  animation: slideToast 0.3s ease;
}
@keyframes slideToast {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border-subtle);
  padding: 2.5rem 0;
  background: var(--bg-surface);
  font-size: 0.88rem;
  color: var(--text-muted);
}
.footer-content {
  display: flex;
  justify-content: space-between;
