// script.js - Bespoke Interactivity for AquaVibe Marine & Aquatics
document.addEventListener('DOMContentLoaded', () => {
  // Theme Toggle
  const themeToggleBtn = document.getElementById('themeToggleBtn');
  const htmlRoot = document.documentElement;

  themeToggleBtn?.addEventListener('click', () => {
    const currentTheme = htmlRoot.getAttribute('data-theme') || 'light';
    const nextTheme = currentTheme === 'light' ? 'dark' : 'light';
    htmlRoot.setAttribute('data-theme', nextTheme);
  });

  // Mobile Drawer
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const mobileDrawer = document.getElementById('mobileDrawer');
  const closeDrawerBtn = document.getElementById('closeDrawerBtn');

  mobileToggle?.addEventListener('click', () => mobileDrawer?.classList.add('open'));
  closeDrawerBtn?.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  document.querySelectorAll('.drawer-link').forEach(link => {
    link.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  });

  // Toast Notification System
  function showToast(message) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    container.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s';
      setTimeout(() => toast.remove(), 300);
    }, 3200);
  }
  window.showToast = showToast;

  // Contact Modal
  const modalBackdrop = document.getElementById('contactModalBackdrop');
  const openModalBtn = document.getElementById('openContactModalBtn');
  const drawerContactBtn = document.getElementById('drawerContactBtn');
  const closeModalBtn = document.getElementById('closeContactModalBtn');
  const contactForm = document.getElementById('contactIntakeForm');

  function openModal() {
    modalBackdrop?.classList.add('open');
    mobileDrawer?.classList.remove('open');
  }
  function closeModal() {
    modalBackdrop?.classList.remove('open');
  }

  openModalBtn?.addEventListener('click', openModal);
  drawerContactBtn?.addEventListener('click', openModal);
  closeModalBtn?.addEventListener('click', closeModal);
  modalBackdrop?.addEventListener('click', (e) => {
    if (e.target === modalBackdrop) closeModal();
  });

  contactForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = document.getElementById('contactName').value;
    closeModal();
    showToast('✨ Thank you, ' + name + '! Your inquiry was submitted.');
    contactForm.reset();
  });

  // FAQ Accordion
  document.querySelectorAll('.faq-question').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !isExpanded);
      item.classList.toggle('active');
    });
  });


      // Aquarium Calculator Logic
      const lSlider = document.getElementById('tankLength');
      const wSlider = document.getElementById('tankWidth');
      const hSlider = document.getElementById('tankHeight');
      const ecoSelect = document.getElementById('ecosystemType');

      function calculateAquarium() {
        const l = parseFloat(lSlider?.value || 36);
        const w = parseFloat(wSlider?.value || 18);
        const h = parseFloat(hSlider?.value || 24);

        document.getElementById('tankLengthVal').textContent = l;
        document.getElementById('tankWidthVal').textContent = w;
        document.getElementById('tankHeightVal').textContent = h;

        // Gallons = (L x W x H) / 231
        const gallons = Math.round((l * w * h) / 231);
        const liters = Math.round(gallons * 3.78541);
        const flowGPH = gallons * 10;
        const watts = Math.round(gallons * 3);
        const fishCount = Math.round(gallons / 3);

        document.getElementById('waterGallons').textContent = gallons + ' Gallons';
        document.getElementById('waterLiters').textContent = '(' + liters + ' Liters)';
        document.getElementById('filterFlowRate').textContent = flowGPH + ' GPH';
        document.getElementById('heaterWattage').textContent = watts + ' Watts';
        document.getElementById('fishCapacity').textContent = 'Up to ' + fishCount + ' community fish';
      }

      [lSlider, wSlider, hSlider, ecoSelect].forEach(el => el?.addEventListener('input', calculateAquarium));
      calculateAquarium();

      document.getElementById('bookAquariumConsultBtn')?.addEventListener('click', () => {
        showToast('🐠 Consultation request logged! An aquatic biologist will contact you within 24h.');
      });

});

css:
:root {
    --primary: #0077B6;
    --primary-hover: #023E8A;
    --secondary: #FF7F50;
    --accent: #00B4D8;
    --bg: #F8FAFC;
    --surface: #FFFFFF;
    --text: #0F172A;
    --muted: #64748B;
    --border: #E2E8F0;
    --glow: rgba(0, 119, 182, 0.15);
    --shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.1);
    --radius: 12px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Plus Jakarta Sans', sans-serif;
    background-color: var(--bg);
    color: var(--text);
    line-height: 1.6;
    overflow-x: hidden;
}

h1, h2, h3 {
    font-family: 'Syne', sans-serif;
    font-weight: 800;
    line-height: 1.1;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 2rem;
}

.grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

/* Navigation */
.navbar {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
    height: 80px;
    display: flex;
    align-items: center;
}

.navbar .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    text-decoration: none;
    color: var(--primary);
    font-weight: 700;
    font-size: 1.5rem;
}

.nav-links {
    display: flex;
    gap: 2.5rem;
    align-items: center;
}

.nav-links a {
    text-decoration: none;
    color: var(--text);
    font-weight: 500;
    transition: color 0.3s ease;
}

.nav-links a:hover {
    color: var(--primary);
}

.mobile-toggle {
    display: none;
    flex-direction: column;
    gap: 6px;
    background: none;
    border: none;
    cursor: pointer;
}

.mobile-toggle span {
    width: 25px;
    height: 2px;
    background: var(--text);
    transition: 0.3s;
}

/* Buttons */
.btn {
    padding: 0.75rem 1.5rem;
    border-radius: var(--radius);
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    border: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: inherit;
}

.btn-primary {
    background: var(--primary);
    color: white;
}

.btn-primary:hover {
    background: var(--primary-hover);
    transform: translateY(-2px);
    box-shadow: 0 10px 20px var(--glow);
}

.btn-outline {
    background: transparent;
    border: 2px solid var(--primary);
    color: var(--primary);
}

.btn-outline:hover {
    background: var(--primary);
    color: white;
}

.btn-lg {
    padding: 1rem 2rem;
    font-size: 1.1rem;
}

/* Hero Section */
.hero {
    padding: 100px 0;
}

.badge {
    background: var(--glow);
    color: var(--primary);
    padding: 0.5rem 1rem;
    border-radius: 50px;
    font-size: 0.875rem;
    font-weight: 700;
    display: inline-block;
    margin-bottom: 1.5rem;
}

.hero h1 {
    font-size: clamp(2.5rem, 5vw, 4.5rem);
    margin-bottom: 1.5rem;
}

.hero p {
    font-size: 1.25rem;
    color: var(--muted);
    margin-bottom: 2.5rem;
    max-width: 500px;
}

.hero-actions {
    display: flex;
    gap: 1rem;
}

.hero-image {
    position: relative;
}

.floating-img {
    width: 100%;
    border-radius: 24px;
    box-shadow: var(--shadow);
    animation: float 6s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-20px); }
}

.stat-card {
    position: absolute;
    bottom: -20px;
    left: -20px;
    background: white;
    padding: 1.5rem;
    border-radius: 16px;
    box-shadow: var(--shadow);
    display: flex;
    flex-direction: column;
}

.stat-num {
    font-size: 2rem;
    font-weight: 800;
    color: var(--primary);
}

/* Showcase */
.showcase {
    padding: 100px 0;
    background: white;
}

.section-header {
    text-align: center;
    margin-bottom: 4rem;
}

.section-header h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.species-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.species-card {
    background: var(--bg);
    border-radius: var(--radius);
    overflow: hidden;
    transition: 0.3s;
    border: 1px solid var(--border);
}

.species-card:hover {
    transform: translateY(-10px);
    box-shadow: var(--shadow);
}

.species-card img {
    width: 100%;
    height: 240px;
    object-fit: cover;
}

.card-body {
    padding: 1.5rem;
}

.card-body h3 {
    margin-bottom: 0.75rem;
}

.price-tag {
    display: block;
    margin-top: 1rem;
    font-weight: 700;
    color: var(--primary);
}

/* Calculator */
.calculator-section {
    padding: 100px 0;
}

.calc-card {
    background: var(--surface);
    padding: 3rem;
    border-radius: 24px;
    box-shadow: var(--shadow);
    max-width: 800px;
    margin: 0 auto;
}

.calc-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
    margin-bottom: 3rem;
}

.input-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.input-group label {
    font-weight: 600;
    font-size: 0.9rem;
}

.input-group input, .input-group select {
    padding: 0.75rem;
    border: 1px solid var(--border);
    border-radius: 8px;
    font-family: inherit;
}

.calc-results {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
}

.result-item {
    background: var(--bg);
    padding: 1.5rem;
    border-radius: 12px;
    text-align: center;
}

.result-item.highlight {
    background: var(--primary);
    color: white;
}

.result-item .label {
    display: block;
    font-size: 0.8rem;
    margin-bottom: 0.5rem;
    opacity: 0.8;
}

.result-item .value {
    font-size: 1.5rem;
    font-weight: 800;
}

/* FAQ */
.faq-section {
    padding: 100px 0;
}

.accordion {
    max-width: 700px;
    margin: 0 auto;
}

.accordion-item {
    border-bottom: 1px solid var(--border);
}

.accordion-trigger {
    width: 100%;
    padding: 1.5rem 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.1rem;
    font-weight: 600;
    text-align: left;
    font-family: inherit;
    color: var(--text);
}

.accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease-out;
}

.accordion-content p {
    padding-bottom: 1.5rem;
    color: var(--muted);
}

.accordion-item.active .accordion-content {
    max-height: 200px;
}

.accordion-item.active .icon {
    transform: rotate(180deg);
}

/* Footer */
footer {
    background: #023E8A;
    color: white;
    padding: 80px 0 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    color: white;
    margin-bottom: 1.5rem;
}

.footer-links {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.footer-links a {
    color: rgba(255,255,255,0.7);
    text-decoration: none;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    border-radius: 8px;
    border: none;
}

.newsletter-form button {
    background: var(--secondary);
    color: white;
    border: none;
    padding: 0.75rem 1.5rem;
    border-radius: 8px;
    cursor: pointer;
}

.footer-bottom {
    border-top: 1px solid rgba(255,255,255,0.1);
    padding-top: 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

/* Modal */
.modal {
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.8);
    backdrop-filter: blur(8px);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 2000;
    padding: 1rem;
}

.modal.active {
    display: flex;
}

.modal-content {
    background: white;
    padding: 3rem;
    border-radius: 24px;
    width: 100%;
    max-width: 500px;
    position: relative;
}

.close-modal {
    position: absolute;
    top: 1.5rem;
    right: 1.5rem;
    font-size: 2rem;
    border: none;
    background: none;
    cursor: pointer;
}

.form-step {
    display: none;
}

.form-step.active {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.btn-row {
    display: flex;
    gap: 1rem;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: #10B981;
    color: white;
    padding: 1rem 2rem;
    border-radius: 12px;
    transform: translateY(200%);
    transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    z-index: 3000;
}

.toast.active {
    transform: translateY(0);
}

#back-to-top {
    background: var(--primary);
    color: white;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: none;
    cursor: pointer;
}

/* Responsive */
@media (max-width: 768px) {
    .grid-2, .calc-grid, .footer-grid {
        grid-template-columns: 1fr;
    }

    .nav-links {
        display: none;
    }

    .mobile-toggle {
        display: flex;
    }

    .hero {
        padding: 60px 0;
    }

    .hero-content {
        text-align: center;
    }

    .hero-actions {
        justify-content: center;
    }

    .calc-results {
        grid-template-columns: 1fr;
    }
}

