document.addEventListener('DOMContentLoaded', () => {
    // Calculator Logic
    const lengthInput = document.getElementById('calc-length');
    const widthInput = document.getElementById('calc-width');
    const heightInput = document.getElementById('calc-height');
    const salinityInput = document.getElementById('target-salinity');

    const resLiters = document.getElementById('res-liters');
    const resGallons = document.getElementById('res-gallons');
    const resSalt = document.getElementById('res-salt');

    function updateCalculator() {
        const l = parseFloat(lengthInput.value) || 0;
        const w = parseFloat(widthInput.value) || 0;
        const h = parseFloat(heightInput.value) || 0;
        const sal = parseFloat(salinityInput.value) || 0;

        const liters = (l * w * h) / 1000;
        const gallons = liters * 0.264172;
        // Approx 35g of salt per liter for 35ppt
        const saltKg = (liters * sal) / 1000;

        resLiters.textContent = liters.toFixed(1);
        resGallons.textContent = gallons.toFixed(1);
        resSalt.textContent = saltKg.toFixed(2);
    }

    [lengthInput, widthInput, heightInput, salinityInput].forEach(input => {
        input.addEventListener('input', updateCalculator);
    });

    // Accordion
    const accordionTriggers = document.querySelectorAll('.accordion-trigger');
    accordionTriggers.forEach(trigger => {
        trigger.addEventListener('click', () => {
            const item = trigger.parentElement;
            const isActive = item.classList.contains('active');

            // Close all others
            document.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));

            if (!isActive) {
                item.classList.add('active');
            }
        });
    });

    // Mobile Nav Toggle
    const mobileToggle = document.querySelector('.mobile-toggle');
    const navLinks = document.querySelector('.nav-links');

    mobileToggle.addEventListener('click', () => {
        navLinks.style.display = navLinks.style.display === 'flex' ? 'none' : 'flex';
        navLinks.style.flexDirection = 'column';
        navLinks.style.position = 'absolute';
        navLinks.style.top = '80px';
        navLinks.style.left = '0';
        navLinks.style.width = '100%';
        navLinks.style.background = 'white';
        navLinks.style.padding = '2rem';
        navLinks.style.borderBottom = '1px solid var(--border)';
    });

    // Back to top
    const btt = document.getElementById('back-to-top');
    btt.addEventListener('click', () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    });

    // Form Handling
    const bookingForm = document.getElementById('booking-form');
    bookingForm.addEventListener('submit', (e) => {
        e.preventDefault();
        toggleModal('booking-modal');
        showToast('Consultation request sent!');
        bookingForm.reset();
        nextStep(1);
    });

    const newsletterForm = document.getElementById('newsletter-form');
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        showToast('Subscribed to reef alerts!');
        newsletterForm.reset();
    });
});

function toggleModal(id) {
    const modal = document.getElementById(id);
    modal.classList.toggle('active');
}

function nextStep(step) {
    document.querySelectorAll('.form-step').forEach(s => s.classList.remove('active'));
    document.getElementById(`step-${step}`).classList.add('active');
}

function showToast(msg) {
    const toast = document.getElementById('toast');
    toast.textContent = msg;
    toast.classList.add('active');
    setTimeout(() => {
        toast.classList.remove('active');
    }, 3000);
}

