// script.js - Bespoke Interactivity for PurePasture Creamery
document.addEventListener('DOMContentLoaded', () => {
  // Theme Toggle
  const themeToggleBtn = document.getElementById('themeToggleBtn');
  const htmlRoot = document.documentElement;

  themeToggleBtn?.addEventListener('click', () => {
    const currentTheme = htmlRoot.getAttribute('data-theme') || 'light';
    const nextTheme = currentTheme === 'light' ? 'dark' : 'light';
    htmlRoot.setAttribute('data-theme', nextTheme);
  });

  // Mobile Drawer
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const mobileDrawer = document.getElementById('mobileDrawer');
  const closeDrawerBtn = document.getElementById('closeDrawerBtn');

  mobileToggle?.addEventListener('click', () => mobileDrawer?.classList.add('open'));
  closeDrawerBtn?.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  document.querySelectorAll('.drawer-link').forEach(link => {
    link.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  });

  // Toast Notification System
  function showToast(message) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    container.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s';
      setTimeout(() => toast.remove(), 300);
    }, 3200);
  }
  window.showToast = showToast;

  // Contact Modal
  const modalBackdrop = document.getElementById('contactModalBackdrop');
  const openModalBtn = document.getElementById('openContactModalBtn');
  const drawerContactBtn = document.getElementById('drawerContactBtn');
  const closeModalBtn = document.getElementById('closeContactModalBtn');
  const contactForm = document.getElementById('contactIntakeForm');

  function openModal() {
    modalBackdrop?.classList.add('open');
    mobileDrawer?.classList.remove('open');
  }
  function closeModal() {
    modalBackdrop?.classList.remove('open');
  }

  openModalBtn?.addEventListener('click', openModal);
  drawerContactBtn?.addEventListener('click', openModal);
  closeModalBtn?.addEventListener('click', closeModal);
  modalBackdrop?.addEventListener('click', (e) => {
    if (e.target === modalBackdrop) closeModal();
  });

  contactForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = document.getElementById('contactName').value;
    closeModal();
    showToast('✨ Thank you, ' + name + '! Your inquiry was submitted.');
    contactForm.reset();
  });

  // FAQ Accordion
  document.querySelectorAll('.faq-question').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !isExpanded);
      item.classList.toggle('active');
    });
  });


      // Universal Estimator Logic
      let currentRate = 1;
      let currentTierName = 'Essential';
      const tierPills = document.querySelectorAll('.tier-pill');
      const scopeSlider = document.getElementById('scopeSlider');
      const velocitySelect = document.getElementById('velocitySelect');

      function updateEstimator() {
        const units = parseInt(scopeSlider?.value || 3);
        document.getElementById('scopeUnitsVal').textContent = units;

        let velocityMultiplier = 1;
        let days = 14;
        const vel = velocitySelect?.value || 'standard';
        if (vel === 'express') {
          velocityMultiplier = 1.35;
          days = 6;
        } else if (vel === 'instant') {
          velocityMultiplier = 1.75;
          days = 3;
        }

        const basePrice = 850;
        const total = Math.round(basePrice * currentRate * units * velocityMultiplier);

        document.getElementById('calcTotalCost').textContent = '$' + total.toLocaleString();
        document.getElementById('selectedTierLabel').textContent = currentTierName;
        document.getElementById('turnaroundLabel').textContent = days + ' Business Days';
      }

      tierPills.forEach(pill => {
        pill.addEventListener('click', () => {
          tierPills.forEach(p => p.classList.remove('active'));
          pill.classList.add('active');
          currentRate = parseFloat(pill.getAttribute('data-rate'));
          currentTierName = pill.textContent.trim();
          updateEstimator();
        });
      });

      scopeSlider?.addEventListener('input', updateEstimator);
      velocitySelect?.addEventListener('change', updateEstimator);
      updateEstimator();

      document.getElementById('claimQuoteBtn')?.addEventListener('click', () => {
        showToast('✨ Proposal locked! Our director will deliver your formal intake packet within 2 hours.');
      });

});

css:
:root {
    --primary: #003366;
    --primary-light: #004d99;
    --accent: #FF7F50;
    --accent-hover: #ff6329;
    --bg: #fdfdfd;
    --surface: #ffffff;
    --text: #1a202c;
    --text-muted: #64748b;
    --border: #e2e8f0;
    --shadow: 0 10px 30px -10px rgba(0, 51, 102, 0.1);
    --container: 1200px;
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg);
    color: var(--text);
    line-height: 1.6;
    overflow-x: hidden;
}

h1, h2, h3, .logo {
    font-family: 'Playfair Display', serif;
    font-weight: 700;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

.container {
    max-width: var(--container);
    margin: 0 auto;
    padding: 0 2rem;
}

.btn-primary {
    background: var(--primary);
    color: white !important;
    padding: 0.8rem 1.8rem;
    border-radius: 4px;
    font-weight: 500;
    border: none;
    cursor: pointer;
    display: inline-block;
}

.btn-primary:hover {
    background: var(--primary-light);
    transform: translateY(-2px);
}

.btn-secondary {
    background: transparent;
    color: var(--primary);
    padding: 0.8rem 1.8rem;
    border-radius: 4px;
    font-weight: 500;
    border: 1px solid var(--primary);
    cursor: pointer;
}

.btn-secondary:hover {
    background: rgba(0, 51, 102, 0.05);
}

/* Header */
.site-header {
    position: fixed;
    top: 0;
    width: 100%;
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border);
    z-index: 1000;
    padding: 1rem 0;
}

.site-header nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 1.5rem;
    color: var(--primary);
}

.nav-links {
    display: flex;
    align-items: center;
    gap: 2.5rem;
}

.nav-links a {
    font-weight: 500;
    font-size: 0.95rem;
}

.nav-links a:hover {
    color: var(--accent);
}

/* Hero */
.hero {
    height: 90vh;
    position: relative;
    display: flex;
    align-items: center;
    background: url('https://images.unsplash.com/photo-1551730459-92db2a308d6a?auto=format&fit=crop&w=1600&q=80') center/cover no-repeat;
    color: white;
    margin-bottom: 4rem;
}

.hero-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to right, rgba(0, 51, 102, 0.7), transparent);
}

.hero-content {
    position: relative;
    z-index: 1;
    max-width: 700px;
}

.hero h1 {
    font-size: clamp(2.5rem, 6vw, 4.5rem);
    line-height: 1.1;
    margin: 1.5rem 0;
}

.hero p {
    font-size: 1.25rem;
    opacity: 0.9;
    margin-bottom: 2.5rem;
}

.badge {
    background: var(--accent);
    padding: 0.5rem 1rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.hero-actions {
    display: flex;
    gap: 1rem;
}

/* Inventory Section */
.section-header {
    text-align: center;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
    color: var(--primary);
}

.filter-bar {
    display: flex;
    justify-content: center;
    gap: 1rem;
    margin-top: 2rem;
}

.filter-btn {
    padding: 0.6rem 1.5rem;
    border-radius: 30px;
    border: 1px solid var(--border);
    background: white;
    cursor: pointer;
    transition: var(--transition);
    font-weight: 500;
}

.filter-btn.active {
    background: var(--primary);
    color: white;
    border-color: var(--primary);
}

.inventory-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.fish-card {
    background: white;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--border);
    transition: var(--transition);
}

.fish-card:hover {
    transform: translateY(-10px);
    box-shadow: var(--shadow);
}

.fish-img {
    height: 200px;
    overflow: hidden;
}

.fish-img img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.fish-card:hover .fish-img img {
    transform: scale(1.1);
}

.fish-info {
    padding: 1.5rem;
}

.fish-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.stock-status {
    font-size: 0.75rem;
    color: #10b981;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 4px;
}

.stock-status::before {
    content: '';
    width: 8px;
    height: 8px;
    background: #10b981;
    border-radius: 50%;
}

.fish-price {
    font-weight: 700;
    color: var(--primary);
}

/* Source Section */
.source-section {
    padding: 6rem 0;
    background: #f8fafc;
}

.grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.source-image img {
    width: 100%;
    border-radius: 12px;
    box-shadow: var(--shadow);
}

.eyebrow {
    color: var(--accent);
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 2px;
    font-size: 0.8rem;
}

.source-content h2 {
    font-size: 2.8rem;
    margin: 1rem 0 1.5rem;
}

.feature-list {
    margin-top: 2rem;
}

.feature-list li {
    margin-bottom: 1.5rem;
    padding-left: 1.5rem;
    border-left: 3px solid var(--accent);
}

/* Subscription */
.cta-section {
    padding: 6rem 0;
}

.cta-card {
    background: var(--primary);
    color: white;
    border-radius: 24px;
    padding: 4rem;
    display: grid;
    grid-template-columns: 1.5fr 1fr;
    gap: 4rem;
    align-items: center;
}

.pricing-toggle {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 2rem 0 1rem;
}

.switch {
    position: relative;
    display: inline-block;
    width: 50px;
    height: 24px;
}

.switch input { opacity: 0; width: 0; height: 0; }

.slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background-color: rgba(255,255,255,0.2);
    transition: .4s;
    border-radius: 34px;
}

.slider:before {
    position: absolute;
    content: "";
    height: 16px; width: 16px;
    left: 4px; bottom: 4px;
    background-color: white;
    transition: .4s;
    border-radius: 50%;
}

input:checked + .slider {
    background-color: var(--accent);
}

input:checked + .slider:before {
    transform: translateX(26px);
}

.price-display {
    font-size: 3rem;
    font-weight: 700;
    margin-bottom: 2rem;
}

.price-display .currency { font-size: 1.5rem; vertical-align: top; margin-top: 10px; display: inline-block; }

.price-display .period { font-size: 1rem; font-weight: 400; opacity: 0.7; }

.cta-features .feature-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.2rem;
    font-size: 1.1rem;
}

/* FAQ */
.faq-section {
    padding: 6rem 0;
    background: white;
}

.accordion {
    max-width: 800px;
    margin: 3rem auto 0;
}

.accordion-item {
    border-bottom: 1px solid var(--border);
}

.accordion-header {
    width: 100%;
    padding: 1.5rem 0;
    background: none;
    border: none;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 1.1rem;
    font-weight: 600;
    cursor: pointer;
    text-align: left;
    color: var(--primary);
}

.accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease-out;
    color: var(--text-muted);
}

.accordion-item.active .accordion-content {
    max-height: 200px;
    padding-bottom: 1.5rem;
}

/* Footer */
.site-footer {
    background: #001a33;
    color: white;
    padding: 5rem 0 2rem;
}

.grid-4 {
    display: grid;
    grid-template-columns: 1.5fr 1fr 1fr 1.5fr;
    gap: 3rem;
}

.footer-brand .logo {
    color: white;
    margin-bottom: 1.5rem;
}

.footer-brand p { opacity: 0.6; }

.site-footer h4 {
    margin-bottom: 1.5rem;
    font-size: 1.1rem;
}

.site-footer ul li {
    margin-bottom: 0.75rem;
}

.site-footer ul li a {
    opacity: 0.6;
}

.site-footer ul li a:hover { opacity: 1; color: var(--accent); }

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    border-radius: 4px;
    border: none;
    background: rgba(255,255,255,0.1);
    color: white;
}

.newsletter-form button {
    background: var(--accent);
    border: none;
    padding: 0 1.5rem;
    border-radius: 4px;
    color: white;
    cursor: pointer;
}

.footer-bottom {
    margin-top: 5rem;
    padding-top: 2rem;
    border-top: 1px solid rgba(255,255,255,0.1);
    text-align: center;
    font-size: 0.9rem;
    opacity: 0.5;
}

/* Modal */
.modal {
    display: none;
    position: fixed;
    z-index: 2000;
    inset: 0;
    background: rgba(0,0,0,0.5);
    backdrop-filter: blur(5px);
    align-items: center;
    justify-content: center;
}

.modal-content {
    background: white;
    padding: 2.5rem;
    border-radius: 16px;
    max-width: 500px;
    width: 90%;
    position: relative;
}

.close-modal {
    position: absolute;
    top: 1.5rem;
    right: 1.5rem;
    font-size: 1.5rem;
    cursor: pointer;
}

.prep-options {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin: 2rem 0;
}

.prep-card {
    cursor: pointer;
}

.prep-card input { display: none; }

.prep-box {
    border: 1px solid var(--border);
    padding: 1rem;
    border-radius: 8px;
    transition: var(--transition);
}

.prep-card input:checked + .prep-box {
    border-color: var(--accent);
    background: rgba(255,127,80,0.05);
}

.full-width {
    width: 100%;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: #10b981;
    color: white;
    padding: 1rem 2rem;
    border-radius: 8px;
    box-shadow: var(--shadow);
    transform: translateY(150%);
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    z-index: 3000;
}

.toast.show {
    transform: translateY(0);
}

/* Mobile Menu */
.mobile-toggle {
    display: none;
    flex-direction: column;
    gap: 6px;
    background: none;
    border: none;
    cursor: pointer;
}

.mobile-toggle span {
    width: 25px;
    height: 2px;
    background: var(--primary);
    transition: var(--transition);
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .mobile-toggle {
        display: flex;
    }
    .grid-2, .grid-4, .cta-card {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
    .cta-card {
        padding: 2rem;
    }
    .hero-actions {
        flex-direction: column;
    }
    .source-image {
        order: 2;
    }
    .source-content {
        order: 1;
    }
}

js:
const seafoodData = [
    {
        id: 1,
        name: "Wild Alaskan King Salmon",
        price: 24.99,
        category: "finfish",
        img: "https://images.unsplash.com/photo-1534604973900-c43ab4c2e0ab?auto=format&fit=crop&w=800&q=80",
        origin: "Bristol Bay, AK"
    },
    {
        id: 2,
        name: "Atlantic Sea Bass",
        price: 18.50,
        category: "finfish",
        img: "https://images.unsplash.com/photo-1615141982883-c7ad0e69fd62?auto=format&fit=crop&w=800&q=80",
        origin: "Gulf of Maine"
    },
    {
        id: 3,
        name: "Hokkaido Sea Scallops",
        price: 32.00,
        category: "shellfish",
        img: "https://images.unsplash.com/photo-1599481238640-4c1288750d7a?auto=format&fit=crop&w=800&q=80",
        origin: "Northern Japan"
    },
    {
        id: 4,
        name: "Bluefin Tuna Saku",
        price: 45.00,
        category: "finfish",
        img: "https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=800&q=80",
        origin: "Mediterranean"
    },
    {
        id: 5,
        name: "Dungeness Crab",
        price: 28.00,
        category: "crustacean",
        img: "https://images.unsplash.com/photo-1550348245-42552869f446?auto=format&fit=crop&w=800&q=80",
        origin: "Pacific Northwest"
    },
    {
        id: 6,
        name: "Pacific Oysters",
        price: 14.00,
        category: "shellfish",
        img: "https://images.unsplash.com/photo-1615141982883-c7ad0e69fd62?auto=format&fit=crop&w=800&q=80",
        origin: "Puget Sound"
    }
];

// DOM Elements
const inventoryGrid = document.getElementById('inventory-grid');
const filterBtns = document.querySelectorAll('.filter-btn');
const billingToggle = document.getElementById('billing-toggle');
const planPrice = document.getElementById('plan-price');
const toast = document.getElementById('toast');
const modal = document.getElementById('prep-modal');
const closeModal = document.querySelector('.close-modal');

// Initialize Inventory
function renderInventory(items) {
    inventoryGrid.innerHTML = items.map(fish => `
        <div class="fish-card" data-category="${fish.category}">
            <div class="fish-img">
                <img src="${fish.img}" alt="${fish.name}">
            </div>
            <div class="fish-info">
                <div class="fish-meta">
                    <span class="stock-status">Fresh Catch</span>
                    <span class="fish-price">$${fish.price.toFixed(2)} / lb</span>
                </div>
                <h3>${fish.name}</h3>
                <p style="font-size: 0.85rem; color: #64748b; margin-bottom: 1.5rem;">Source: ${fish.origin}</p>
                <button class="btn-secondary full-width" onclick="openPrepModal('${fish.name}')">Select & Prep</button>
            </div>
        </div>
    `).join('');
}

renderInventory(seafoodData);

// Filtering Logic
filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const category = btn.dataset.category;

        if (category === 'all') {
            renderInventory(seafoodData);
        } else {
            const filtered = seafoodData.filter(item => item.category === category);
            renderInventory(filtered);
        }
    });
});

// Pricing Toggle
billingToggle.addEventListener('change', () => {
    if (billingToggle.checked) {
        planPrice.innerText = '71';
    } else {
        planPrice.innerText = '89';
    }
});

// Modal Functionality
function openPrepModal(fishName) {
    document.getElementById('modal-fish-info').innerHTML = `<p>Preparing your <strong>${fishName}</strong>. Choose your preferred style:</p>`;
    modal.style.display = 'flex';
}

closeModal.onclick = () => modal.style.display = 'none';
window.onclick = (e) => { if (e.target == modal) modal.style.display = 'none'; };

function confirmPurchase() {
    const selectedPrep = document.querySelector('input[name="prep"]:checked').value;
    modal.style.display = 'none';
    showToast(`Added to basket with '${selectedPrep}' preparation.`);
}

// Toast Notification
function showToast(message) {
    toast.innerText = message;
    toast.classList.add('show');
    setTimeout(() => {
        toast.classList.remove('show');
    }, 3000);
}

// Accordion Logic
document.querySelectorAll('.accordion-header').forEach(header => {
    header.addEventListener('click', () => {
        const item = header.parentElement;
        const isActive = item.classList.contains('active');

        document.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));

        if (!isActive) {
            item.classList.add('active');
            header.querySelector('.icon').innerText = '-';
        } else {
            header.querySelector('.icon').innerText = '+';
        }
    });
});

// Newsletter Form
document.getElementById('newsletter-form').onsubmit = (e) => {
    e.preventDefault();
    showToast('Success! Check your inbox for our catch reports.');
    e.target.reset();
};

// Mobile Menu Toggle
const mobileToggle = document.querySelector('.mobile-toggle');
const navLinks = document.querySelector('.nav-links');

mobileToggle.onclick = () => {
    navLinks.style.display = navLinks.style.display === 'flex' ? 'none' : 'flex';
    navLinks.style.flexDirection = 'column';
    navLinks.style.position = 'absolute';
    navLinks.style.top = '100%';
    navLinks.style.left = '0';
    navLinks.style.width = '100%';
    navLinks.style.background = 'white';
    navLinks.style.padding = '2rem';
    navLinks.style.boxShadow = 'var(--shadow)';
};

css:
/* styles.css - Bespoke Design System for Blue Anchor Provisions */
:root {
  --bg-app: #f8fafc;
  --bg-surface: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-secondary: #475569;
  --border-subtle: #e2e8f0;
  --primary: #003B5C;
  --primary-hover: #1e293b;
  --accent: #E2725B;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 6px 18px rgba(0,0,0,0.08);
  --shadow-lg: 0 16px 36px rgba(0,0,0,0.12);
  --font-heading: 'Playfair Display', sans-serif;
  --font-body: 'Inter', sans-serif;
}

[data-theme="dark"] {
  --bg-app: #0b1120;
  --bg-surface: #131d31;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-secondary: #cbd5e1;
  --border-subtle: #1e293b;
  --primary: #ffffff;
  --primary-hover: #f1f5f9;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-md: 0 6px 18px rgba(0,0,0,0.5);
  --shadow-lg: 0 16px 36px rgba(0,0,0,0.6);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background: var(--bg-app);
  color: var(--text-main);
  line-height: 1.6;
  overflow-x: hidden;
  transition: background 0.3s ease, color 0.3s ease;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-subtle);
  z-index: 100;
}
[data-theme="dark"] .site-header {
  background: rgba(19, 29, 49, 0.88);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  text-decoration: none;
  color: var(--text-main);
  font-family: var(--font-heading);
  font-size: 1.3rem;
  letter-spacing: -0.02em;
}

.logo-symbol {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
}
[data-theme="dark"] .logo-symbol {
  color: #0f172a;
}

.main-nav {
  display: flex;
  gap: 1.75rem;
}

.nav-link {
  text-decoration: none;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.95rem;
  transition: color 0.2s;
}
.nav-link:hover {
  color: var(--accent);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.icon-btn {
  background: none;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  padding: 0.5rem;
  cursor: pointer;
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.icon-btn:hover {
  background: var(--border-subtle);
  transform: translateY(-1px);
}

.sun-icon { display: none; }
.moon-icon { display: block; }
[data-theme="dark"] .sun-icon { display: block; }
[data-theme="dark"] .moon-icon { display: none; }

.hamburger-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}
.hamburger-btn .bar {
  width: 22px;
  height: 2px;
  background: var(--text-main);
  border-radius: 2px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.75rem 1.4rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  text-decoration: none;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}
.btn-primary {
  background: var(--accent);
  color: #ffffff;
}
.btn-primary:hover {
  filter: brightness(1.1);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(0,0,0,0.15);
}
.btn-outline {
  border-color: var(--border-subtle);
  background: var(--bg-surface);
  color: var(--text-main);
}
.btn-outline:hover {
  border-color: var(--text-main);
  background: var(--border-subtle);
}
.btn-lg {
  padding: 0.95rem 1.85rem;
  font-size: 1.05rem;
}
.btn-block {
  width: 100%;
}

/* Hero */
.hero-section {
  padding: 5rem 0;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  align-items: center;
  gap: 3.5rem;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.95rem;
  background: var(--border-subtle);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1.5rem;
}
.pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.3);
}

.hero-title {
  font-family: var(--font-heading);
  font-size: clamp(2.4rem, 4.2vw, 3.8rem);
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 1.25rem;
}
.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 520px;
  margin-bottom: 2rem;
}

.hero-cta-group {
  display: flex;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.hero-metrics {
  display: flex;
  gap: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-subtle);
}
.metric-num {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-main);
}
.metric-lbl {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.visual-frame {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border-subtle);
}
.hero-img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.visual-frame:hover .hero-img {
  transform: scale(1.04);
}
.floating-badge {
  position: absolute;
  bottom: 1.5rem;
  left: 1.5rem;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(8px);
  color: #fff;
  padding: 0.45rem 0.9rem;
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
}

/* Interactive Section */
.interactive-section {
  padding: 5rem 0;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}
.section-head {
  margin-bottom: 3rem;
}
.text-center {
  text-align: center;
}
.eyebrow {
  display: inline-block;
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 0.5rem;
}
.section-head h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 3.2vw, 2.5rem);
  letter-spacing: -0.02em;
}
.section-sub {
  color: var(--text-muted);
  max-width: 600px;
  margin: 0.5rem auto 0;
}

.widget-interactive-box {
  background: var(--bg-app);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  box-shadow: var(--shadow-md);
  max-width: 960px;
  margin: 0 auto;
}

.calculator-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 2.5rem;
}

.calc-input-pane h3 {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  margin-bottom: 0.35rem;
}
.calc-input-pane p {
  font-size: 0.88rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.input-field {
  margin-bottom: 1.25rem;
}
.input-field label {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
  color: var(--text-main);
}
.slider-input {
  width: 100%;
  accent-color: var(--accent);
  cursor: pointer;
}
.select-input {
  width: 100%;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-family: inherit;
  font-weight: 500;
}

.pill-selector {
  display: flex;
  gap: 0.5rem;
}
.tier-pill {
  flex: 1;
  padding: 0.6rem;
  border-radius: var(--radius-sm);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
}
.tier-pill.active {
  background: var(--text-main);
  color: var(--bg-surface);
  border-color: var(--text-main);
}

.calc-output-pane {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: var(--shadow-sm);
}

.result-card {
  text-align: center;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border-subtle);
}
.result-label {
  font-size: 0.82rem;
  color: var(--text-muted);
  display: block;
  margin-bottom: 0.25rem;
}
.result-number {
  font-family: var(--font-heading);
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--accent);
  display: block;
}
.result-sub {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.result-details {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin: 1.5rem 0;
  font-size: 0.88rem;
}
.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Showcase Grid */
.showcase-section {
  padding: 5rem 0;
}
.showcase-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}
.showcase-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.25s, box-shadow 0.25s;
}
.showcase-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.card-img-wrap {
  height: 220px;
  overflow: hidden;
}
.card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.showcase-card:hover .card-img {
  transform: scale(1.06);
}
.card-body {
  padding: 1.75rem;
}
.card-tag {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
  margin-bottom: 0.4rem;
  display: block;
}
.card-body h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}
.card-body p {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* Testimonials */
.testimonials-section {
  padding: 5rem 0;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
}
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  max-width: 900px;
  margin: 0 auto;
}
.testimonial-card {
  background: var(--bg-app);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 2rem;
}
.star-rating {
  color: #f59e0b;
  margin-bottom: 1rem;
  font-size: 1.1rem;
}
.testimonial-card p {
  font-size: 0.95rem;
  color: var(--text-secondary);
  font-style: italic;
  margin-bottom: 1.25rem;
}
.author-meta strong {
  display: block;
  font-size: 0.95rem;
}
.author-meta span {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* FAQ */
.faq-section {
  padding: 5rem 0;
}
.faq-accordion {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.faq-item {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  text-align: left;
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-arrow {
  font-size: 1.3rem;
  transition: transform 0.25s;
}
.faq-item.active .faq-arrow {
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  padding: 0 1.5rem;
  color: var(--text-muted);
  font-size: 0.92rem;
}
.faq-item.active .faq-answer {
  max-height: 200px;
  padding: 0 1.5rem 1.25rem;
}

/* Modal Dialog */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s;
  padding: 1.5rem;
}
.modal-backdrop.open {
  opacity: 1;
  visibility: visible;
}
.modal-dialog {
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  padding: 2.25rem;
  width: 100%;
  max-width: 500px;
  box-shadow: var(--shadow-lg);
}
.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}
.modal-header h3 {
  font-family: var(--font-heading);
}
.drawer-close-btn {
  background: none;
  border: none;
  font-size: 1.6rem;
  cursor: pointer;
  color: var(--text-main);
}
.form-group {
  margin-bottom: 1.2rem;
}
.form-group label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
}
.form-group input, .form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  background: var(--bg-app);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  font-family: inherit;
}

/* Mobile Drawer */
.mobile-drawer {
  position: fixed;
  inset: 0;
  background: var(--bg-surface);
  z-index: 1002;
  transform: translateY(-100%);
  transition: transform 0.3s ease;
  padding: 2rem;
  display: flex;
  flex-direction: column;
}
.mobile-drawer.open {
  transform: translateY(0);
}
.drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}
.drawer-links {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  font-size: 1.25rem;
  font-weight: 600;
}
.drawer-link {
  text-decoration: none;
  color: var(--text-main);
}

/* Toast */
.toast-container {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.toast {
  background: var(--text-main);
  color: var(--bg-surface);
  padding: 0.9rem 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.9rem;
  font-weight: 500;
  animation: slideToast 0.3s ease;
}
@keyframes slideToast {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border-subtle);
  padding: 2.5rem 0;
  background: var(--bg-surface);
  font-size: 0.88rem;
  color: var(--text-muted);
}
.footer-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-links {
  display: flex;
  gap: 1.5rem;
}
.footer-links a {
  color: var(--text-muted);
  text-decoration: none;
}
.footer-links a:hover {
  color: var(--accent);
}

@media (max-width: 900px) {
  .hero-grid, .calculator-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .main-nav {
    display: none;
  }
  .hamburger-btn {
    display: flex;
  }
  .footer-content {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
}

