// script.js - E-Commerce & Sneaker Boutique Logic
document.addEventListener('DOMContentLoaded', () => {
  // Theme Toggle
  const themeToggleBtn = document.getElementById('themeToggleBtn');
  const htmlRoot = document.documentElement;

  themeToggleBtn.addEventListener('click', () => {
    const currentTheme = htmlRoot.getAttribute('data-theme') || 'light';
    const nextTheme = currentTheme === 'light' ? 'dark' : 'light';
    htmlRoot.setAttribute('data-theme', nextTheme);
  });

  // Mobile Drawer
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const mobileDrawer = document.getElementById('mobileDrawer');
  const closeDrawerBtn = document.getElementById('closeDrawerBtn');

  mobileToggle?.addEventListener('click', () => mobileDrawer?.classList.add('open'));
  closeDrawerBtn?.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  document.querySelectorAll('.drawer-link').forEach(link => {
    link.addEventListener('click', () => mobileDrawer?.classList.remove('open'));
  });

  // Toast System
  function showToast(message) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    container.appendChild(toast);
    setTimeout(() => {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity 0.3s';
      setTimeout(() => toast.remove(), 300);
    }, 3200);
  }

  // Cart Management
  let cart = [];
  const cartDrawer = document.getElementById('cartDrawer');
  const cartOverlay = document.getElementById('cartOverlay');
  const openCartBtn = document.getElementById('openCartBtn');
  const closeCartBtn = document.getElementById('closeCartBtn');
  const cartCountBadge = document.getElementById('cartCountBadge');
  const cartDrawerCount = document.getElementById('cartDrawerCount');
  const cartItemsList = document.getElementById('cartItemsList');
  const cartFooter = document.getElementById('cartFooter');
  const cartSubtotal = document.getElementById('cartSubtotal');

  function openCart() {
    cartDrawer?.classList.add('open');
    cartOverlay?.classList.add('open');
  }

  function closeCart() {
    cartDrawer?.classList.remove('open');
    cartOverlay?.classList.remove('open');
  }

  openCartBtn?.addEventListener('click', openCart);
  closeCartBtn?.addEventListener('click', closeCart);
  cartOverlay?.addEventListener('click', closeCart);

  function renderCart() {
    const totalCount = cart.length;
    cartCountBadge.textContent = totalCount;
    cartDrawerCount.textContent = totalCount;

    if (totalCount === 0) {
      cartItemsList.innerHTML = `
        <div class="cart-empty-state">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>
          <p>Your shopping bag is currently empty.</p>
          <a href="#featured" class="btn btn-outline btn-sm" id="shopNowCartBtn">Explore New Drops</a>
        </div>
      `;
      document.getElementById('shopNowCartBtn')?.addEventListener('click', closeCart);
      cartFooter.style.display = 'none';
      return;
    }

    cartFooter.style.display = 'block';
    let subtotal = 0;

    cartItemsList.innerHTML = cart.map((item, idx) => {
      subtotal += item.price;
      return `
        <div class="cart-line-item">
          <img src="${item.img}" alt="${item.name}" class="cart-item-img">
          <div class="cart-item-details">
            <div class="cart-item-name">${item.name}</div>
            <div class="cart-item-meta">Color: ${item.color} • Size: US ${item.size}</div>
            <div class="cart-item-price">$${item.price.toFixed(2)}</div>
          </div>
          <button class="cart-item-remove" data-index="${idx}" aria-label="Remove item">✕</button>
        </div>
      `;
    }).join('');

    cartSubtotal.textContent = '$' + subtotal.toFixed(2);

    document.querySelectorAll('.cart-item-remove').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const index = parseInt(e.currentTarget.getAttribute('data-index'));
        cart.splice(index, 1);
        renderCart();
        showToast('Item removed from bag');
      });
    });
  }

  function addToCart(item) {
    cart.push(item);
    renderCart();
    openCart();
    showToast('✨ Added to Bag: ' + item.name);
  }

  // 360 Customizer Studio Logic
  let selectedColorName = 'Hyper Crimson';
  let selectedPrice = 198;
  let selectedShoeImg = 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1000&q=80';
  let selectedSize = '9';

  const colorButtons = document.querySelectorAll('.color-btn');
  const customizerShoeImg = document.getElementById('customizerShoeImg');
  const activeColorTag = document.getElementById('activeColorTag');
  const customizerPrice = document.getElementById('customizerPrice');

  colorButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      colorButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      selectedColorName = btn.getAttribute('data-name');
      selectedPrice = parseFloat(btn.getAttribute('data-price'));
      selectedShoeImg = btn.getAttribute('data-img');

      customizerShoeImg.src = selectedShoeImg;
      activeColorTag.textContent = 'Colorway: ' + selectedColorName;
      customizerPrice.textContent = '$' + selectedPrice.toFixed(2);

      // Micro animation
      customizerShoeImg.style.transform = 'scale(0.96)';
      setTimeout(() => { customizerShoeImg.style.transform = 'scale(1)'; }, 150);
    });
  });

  const sizeChips = document.querySelectorAll('.size-chip');
  sizeChips.forEach(chip => {
    chip.addEventListener('click', () => {
      sizeChips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      selectedSize = chip.getAttribute('data-size');
      showToast('Selected size: US ' + selectedSize);
    });
  });

  document.getElementById('addCustomizerToCartBtn')?.addEventListener('click', () => {
    addToCart({
      name: 'Apex Studio Studio Edition',
      color: selectedColorName,
      size: selectedSize,
      price: selectedPrice,
      img: selectedShoeImg
    });
  });

  // Quick Add from Grid
  document.querySelectorAll('.quick-add-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const name = btn.getAttribute('data-name');
      const price = parseFloat(btn.getAttribute('data-price'));
      const color = btn.getAttribute('data-color');
      const size = btn.getAttribute('data-size');
      const card = btn.closest('.product-card');
      const img = card?.querySelector('.prod-img')?.src || selectedShoeImg;

      addToCart({ name, price, color, size, img });
    });
  });

  // FAQ Accordion
  document.querySelectorAll('.faq-question').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !isExpanded);
      item.classList.toggle('active');
    });
  });

  // Size Quiz Modal Trigger
  document.getElementById('sizeGuideBtn')?.addEventListener('click', () => {
    showToast('💡 Recommendation: If you wear standard Nike or Adidas US 9, select US 9 for optimal lock-in.');
  });

  // Checkout Button
  document.getElementById('cartCheckoutBtn')?.addEventListener('click', () => {
    showToast('🎉 Checkout initiated! Connecting to secure payment gateway...');
    setTimeout(() => {
      cart = [];
      renderCart();
      closeCart();
      showToast('✅ Order confirmed! Receipt dispatched to your email.');
    }, 2000);
  });

  // Newsletter Form
  document.getElementById('newsletterForm')?.addEventListener('submit', (e) => {
    e.preventDefault();
    const email = document.getElementById('newsEmailInput').value;
    showToast('🎉 Welcome to Priority Access! VIP code dispatched to ' + email);
    e.target.reset();
  });
});

css:
/* AuraHealth Premier Medical Group Design System */
:root {
  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Cinzel', serif;

  /* Color Tokens - Light */
  --bg: #f8fafc;
  --surface: #ffffff;
  --surface-alt: #f1f5f9;
  --surface-glass: rgba(255, 255, 255, 0.85);
  --border: #e2e8f0;
  --border-focus: #0ea5e9;

  --primary: #0284c7;
  --primary-hover: #0369a1;
  --primary-light: #e0f2fe;
  --secondary: #0f172a;
  --accent: #10b981;

  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 14px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 30px rgba(0,0,0,0.1);
  --shadow-glow: 0 0 25px rgba(14, 165, 233, 0.25);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-theme="dark"] {
  --bg: #090d16;
  --surface: #0f172a;
  --surface-alt: #1e293b;
  --surface-glass: rgba(15, 23, 42, 0.85);
  --border: #334155;
  --border-focus: #38bdf8;

  --primary: #38bdf8;
  --primary-hover: #7dd3fc;
  --primary-light: rgba(56, 189, 248, 0.15);
  --secondary: #f8fafc;
  --accent: #34d399;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-light: #64748b;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-md: 0 4px 14px rgba(0,0,0,0.4);
  --shadow-lg: 0 12px 30px rgba(0,0,0,0.5);
  --shadow-glow: 0 0 30px rgba(56, 189, 248, 0.35);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-main);
  background-color: var(--bg);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.3s ease, color 0.3s ease;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Container */
.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.max-w-narrow {
  max-width: 860px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  cursor: pointer;
  border: 1px solid transparent;
  transition: var(--transition);
  text-decoration: none;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary) 0%, #0284c7 100%);
  color: #ffffff;
  box-shadow: 0 4px 16px rgba(14, 165, 233, 0.35);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 22px rgba(14, 165, 233, 0.45);
}

.btn-outline {
  background: transparent;
  border-color: var(--border);
  color: var(--text-main);
}

.btn-outline:hover {
  background: var(--surface-alt);
  border-color: var(--primary);
  transform: translateY(-2px);
}

.btn-lg {
  padding: 0.9rem 2rem;
  font-size: 1.05rem;
}

.btn-block {
  width: 100%;
}

.icon-btn {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-main);
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.icon-btn:hover {
  border-color: var(--primary);
  background: var(--surface-alt);
}

[data-theme="light"] .moon-icon { display: block; }
[data-theme="light"] .sun-icon { display: none; }
[data-theme="dark"] .moon-icon { display: none; }
[data-theme="dark"] .sun-icon { display: block; }

/* Header & Nav */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  background-color: var(--surface-glass);
  border-bottom: 1px solid var(--border);
  transition: var(--transition);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 76px;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--text-main);
}

.logo-symbol {
  width: 38px;
  height: 38px;
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
}

.brand-text {
  font-size: 1.3rem;
  font-weight: 500;
  letter-spacing: -0.02em;
}

.brand-text strong {
  font-weight: 800;
  color: var(--primary);
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-link {
  color: var(--text-muted);
  text-decoration: none;
  font-weight: 500;
  font-size: 0.95rem;
  transition: var(--transition);
}

.nav-link:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hamburger-btn {
  display: none;
  flex-direction: column;
  justify-content: space-between;
  width: 32px;
  height: 22px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

.hamburger-btn .bar {
  width: 100%;
  height: 3px;
  background-color: var(--text-main);
  border-radius: 2px;
  transition: var(--transition);
}

/* Mobile Drawer */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background-color: var(--surface);
  box-shadow: var(--shadow-lg);
  z-index: 1000;
  transition: right 0.35s ease-in-out;
  padding: 2rem;
  display: flex;
  flex-direction: column;
}

.mobile-drawer.open {
  right: 0;
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2rem;
}

.drawer-close-btn {
  background: none;
  border: none;
  font-size: 2rem;
  color: var(--text-main);
  cursor: pointer;
}

.drawer-links {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.drawer-link {
  color: var(--text-main);
  text-decoration: none;
  font-size: 1.1rem;
  font-weight: 500;
}

/* Hero Section */
.hero-section {
  position: relative;
  padding: 5rem 0 4rem;
  overflow: hidden;
}

.hero-glow {
  position: absolute;
  top: -120px;
  right: 10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(14, 165, 233, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  align-items: center;
  gap: 3.5rem;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--primary-light);
  color: var(--primary);
  padding: 0.4rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
}

.pulse-dot {
  width: 8px;
  height: 8px;
  background-color: var(--accent);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--accent);
  animation: pulseAnim 2s infinite;
}

@keyframes pulseAnim {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(1.3); }
}

.hero-title {
  font-size: clamp(2.4rem, 4.5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 1.25rem;
  color: var(--text-main);
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 2.25rem;
  max-width: 560px;
}

.hero-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.hero-social-proof {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}

.avatar-stack {
  display: flex;
}

.avatar-img {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--surface);
  object-fit: cover;
  margin-left: -12px;
}

.avatar-stack .avatar-img:first-child {
  margin-left: 0;
}

.proof-text {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.star-rating {
  color: #f59e0b;
  font-size: 1rem;
}

/* Hero Visual */
.image-card-wrapper {
  position: relative;
}

.hero-main-img {
  width: 100%;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  object-fit: cover;
  aspect-ratio: 4/3;
}

.glass-stat-card {
  position: absolute;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  background: var(--surface-glass);
  border: 1px solid var(--border);
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  gap: 1rem;
}

.card-top-right {
  top: -24px;
  right: -20px;
}

.card-bottom-left {
  bottom: -24px;
  left: -20px;
}

.stat-badge-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.stat-accent {
  background: rgba(16, 185, 129, 0.15);
  color: var(--accent);
}

.stat-value {
  display: block;
  font-weight: 800;
  font-size: 1.25rem;
  color: var(--text-main);
  line-height: 1.1;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Stats Ribbon */
.stats-ribbon {
  background: var(--surface-alt);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 2rem 0;
}

.ribbon-grid {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.ribbon-item {
  flex: 1;
  min-width: 180px;
  text-align: center;
}

.ribbon-num {
  display: block;
  font-size: 1.9rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1.2;
}

.ribbon-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 500;
}

.ribbon-divider {
  width: 1px;
  height: 40px;
  background: var(--border);
}

/* Section Common */
.section {
  padding: 6rem 0;
}

.section-dark {
  background-color: var(--surface-alt);
}

.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem;
}

.section-tag {
  display: inline-block;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.section-title {
  font-size: clamp(2rem, 3.2vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
}

.section-subtitle {
  color: var(--text-muted);
  font-size: 1.1rem;
}

/* Services Grid */
.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}

.service-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  transition: var(--transition);
  position: relative;
}

.service-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: var(--primary);
}

.featured-service {
  border-color: var(--primary);
  box-shadow: var(--shadow-glow);
}

.featured-badge {
  position: absolute;
  top: -12px;
  right: 24px;
  background: var(--primary);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.3rem 0.85rem;
  border-radius: var(--radius-full);
}

.service-icon {
  width: 56px;
  height: 56px;
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  margin-bottom: 1.5rem;
}

.service-name {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.service-text {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  font-size: 0.95rem;
}

.service-perks {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  font-size: 0.9rem;
}

.service-perks li::before {
  content: '✓';
  color: var(--accent);
  font-weight: bold;
  margin-right: 0.5rem;
}

/* Calculator Section */
.calculator-card {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}

.calc-inputs {
  padding: 3rem;
}

.range-slider {
  width: 100%;
  accent-color: var(--primary);
  height: 6px;
  background: var(--border);
  border-radius: 4px;
  outline: none;
  margin-top: 0.5rem;
}

.slider-display {
  color: var(--primary);
  font-weight: 800;
}

.radio-pill-group {
  display: flex;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.radio-pill {
  padding: 0.5rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  cursor: pointer;
  font-size: 0.9rem;
  transition: var(--transition);
}

.radio-pill:has(input:checked) {
  background: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
  font-weight: 700;
}

.calc-results-panel {
  background: linear-gradient(145deg, var(--surface-alt) 0%, var(--surface) 100%);
  padding: 3rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-left: 1px solid var(--border);
}

.results-heading {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.result-metric-box {
  margin-bottom: 1.5rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border);
}

.result-number {
  display: block;
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--accent);
}

.result-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Faculty Grid */
.faculty-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2.5rem;
}

.faculty-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
}

.faculty-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
}

.faculty-img-wrapper {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
}

.faculty-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.faculty-badge {
  position: absolute;
  bottom: 12px;
  left: 12px;
  background: var(--surface-glass);
  backdrop-filter: blur(8px);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.35rem 0.8rem;
  border-radius: var(--radius-sm);
  color: var(--text-main);
}

.faculty-info {
  padding: 1.75rem;
}

.faculty-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.3rem;
}

.faculty-role {
  display: block;
  font-size: 0.85rem;
  color: var(--primary);
  font-weight: 600;
  margin-bottom: 1rem;
}

.faculty-bio {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* Testimonials Carousel */
.testimonials-carousel {
  max-width: 760px;
  margin: 0 auto 2rem;
  position: relative;
}

.testimonial-card {
  display: none;
  background: var(--surface);
  padding: 3rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
}

.testimonial-card.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.quote-mark {
  font-size: 3.5rem;
  line-height: 1;
  color: var(--primary-light);
  font-family: serif;
}

.testimonial-quote {
  font-size: 1.15rem;
  font-weight: 500;
  line-height: 1.7;
  margin-bottom: 2rem;
  color: var(--text-main);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.author-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
}

.author-name {
  font-size: 1.05rem;
  font-weight: 700;
}

.author-role {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
}

.carousel-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.carousel-dot.active {
  background: var(--primary);
  transform: scale(1.3);
}

/* FAQ Accordion */
.accordion-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.accordion-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--surface);
  overflow: hidden;
  transition: var(--transition);
}

.accordion-trigger {
  width: 100%;
  padding: 1.35rem 1.75rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-main);
  text-align: left;
}

.accordion-icon {
  font-size: 1.5rem;
  line-height: 1;
  color: var(--primary);
  transition: transform 0.3s ease;
}

.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  padding: 0 1.75rem;
  color: var(--text-muted);
}

.accordion-item.active .accordion-content {
  padding-bottom: 1.5rem;
}

/* Contact CTA Box */
.section-cta {
  background: linear-gradient(180deg, var(--bg) 0%, var(--surface-alt) 100%);
}

.cta-box {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 3.5rem;
  box-shadow: var(--shadow-lg);
}

.cta-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.cta-header h2 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.cta-header p {
  color: var(--text-muted);
}

/* Forms */
.form-group {
  margin-bottom: 1.5rem;
}

.form-row {
  display: flex;
  gap: 1.5rem;
}

.flex-1 { flex: 1; }

.form-label {
  display: block;
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--text-main);
}

.form-input, .form-select, .form-textarea {
  width: 100%;
  padding: 0.85rem 1.15rem;
  font-family: inherit;
  font-size: 0.95rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text-main);
  transition: var(--transition);
}

.form-input:focus, .form-select:focus, .form-textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-light);
}

.error-msg {
  display: none;
  font-size: 0.8rem;
  color: #ef4444;
  margin-top: 0.3rem;
}

.form-group.has-error .error-msg {
  display: block;
}

.form-group.has-error .form-input {
  border-color: #ef4444;
}

/* Footer */
.site-footer {
  background-color: var(--surface-alt);
  border-top: 1px solid var(--border);
  padding: 5rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 4rem;
}

.footer-desc {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin: 1rem 0 1.5rem;
  max-width: 320px;
}

.hipaa-badge {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0.4rem 0.8rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
}

.footer-heading {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
}

.footer-nav {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-nav a, .footer-nav li {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  transition: var(--transition);
}

.footer-nav a:hover {
  color: var(--primary);
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 2rem;
}

.bottom-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
  color: var(--text-muted);
  flex-wrap: wrap;
  gap: 1rem;
}

.legal-links {
  display: flex;
  gap: 1.5rem;
}

.legal-links a {
  color: var(--text-muted);
  text-decoration: none;
}

.legal-links a:hover {
  color: var(--primary);
}

/* Modal Dialog */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.modal-backdrop.open {
  display: flex;
}

.modal-dialog {
  background: var(--surface);
  border-radius: var(--radius-lg);
  max-width: 520px;
  width: 100%;
  box-shadow: var(--shadow-lg);
  padding: 2.5rem;
  animation: modalScale 0.25s ease-out;
}

@keyframes modalScale {
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}

.modal-title {
  font-size: 1.4rem;
  font-weight: 800;
}

.modal-close {
  background: none;
  border: none;
  font-size: 1.8rem;
  line-height: 1;
  color: var(--text-muted);
  cursor: pointer;
}

.modal-intro {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
}

/* Toast */
.toast-container {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 2000;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.toast {
  background: var(--surface);
  border: 1px solid var(--accent);
  color: var(--text-main);
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  animation: slideToast 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideToast {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

/* Responsive Media Queries */
@media (max-width: 992px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .hero-subtitle {
    margin: 0 auto 2.25rem;
  }
  .hero-cta-group {
    justify-content: center;
  }
  .hero-social-proof {
    justify-content: center;
  }
  .card-top-right {
    right: 10px;
  }
  .card-bottom-left {
    left: 10px;
  }
  .calculator-card {
    grid-template-columns: 1fr;
  }
  .calc-results-panel {
    border-left: none;
    border-top: 1px solid var(--border);
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .main-nav {
    display: none;
  }
  .hamburger-btn {
    display: flex;
  }
  .ribbon-divider {
    display: none;
  }
  .ribbon-item {
    min-width: 45%;
  }
  .form-row {
    flex-direction: column;
    gap: 0;
  }
  .cta-box {
    padding: 2rem 1.5rem;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

