/* OmniFlow AI - Conversion-Focused SaaS Landing Page Styling */
:root {
  --saas-font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --saas-mono: 'JetBrains Mono', monospace;

  --bg-dark: #07090e;
  --surface-card: #0e121b;
  --surface-card-hover: #141b27;
  --surface-alt: #121824;
  --border-line: #1e293b;

  --primary-color: #6366f1;
  --primary-hover: #4f46e5;
  --primary-glow: rgba(99, 102, 241, 0.35);

  --accent-cyan: #06b6d4;
  --text-white: #ffffff;
  --text-dim: #94a3b8;

  --radius-pill: 9999px;
  --radius-card: 16px;
  --radius-input: 8px;

  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-theme="light"] {
  --bg-dark: #f8fafc;
  --surface-card: #ffffff;
  --surface-card-hover: #f1f5f9;
  --surface-alt: #f1f5f9;
  --border-line: #e2e8f0;

  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --primary-glow: rgba(79, 70, 229, 0.2);

  --accent-cyan: #0891b2;
  --text-white: #0f172a;
  --text-dim: #64748b;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--saas-font);
  background-color: var(--bg-dark);
  color: var(--text-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.saas-container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.max-w-narrow {
  max-width: 820px;
}

/* Banner */
.saas-banner {
  background: linear-gradient(90deg, #4f46e5 0%, #06b6d4 100%);
  color: #ffffff;
  text-align: center;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 0.5rem 1rem;
}

.banner-link {
  color: #ffffff;
  text-decoration: underline;
  margin-left: 0.5rem;
}

/* Header */
.saas-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(7, 9, 14, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-line);
}

[data-theme="light"] .saas-header {
  background: rgba(248, 250, 252, 0.85);
}

.saas-nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.saas-brand {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  color: var(--text-white);
}

.saas-brand-icon {
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, #6366f1 0%, #06b6d4 100%);
  color: #fff;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.saas-brand-text {
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.saas-brand-text strong {
  color: var(--primary-color);
}

.saas-nav {
  display: flex;
  gap: 2rem;
}

.saas-nav-link {
  color: var(--text-dim);
  text-decoration: none;
  font-weight: 500;
  font-size: 0.95rem;
  transition: var(--transition);
}

.saas-nav-link:hover {
  color: var(--primary-color);
}

.saas-nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.saas-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 0.9rem;
  padding: 0.65rem 1.35rem;
  border-radius: var(--radius-pill);
  cursor: pointer;
  border: 1px solid transparent;
  transition: var(--transition);
  text-decoration: none;
}

.saas-btn-primary {
  background: linear-gradient(135deg, var(--primary-color) 0%, #06b6d4 100%);
  color: #ffffff;
  box-shadow: 0 4px 18px var(--primary-glow);
}

.saas-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px var(--primary-glow);
}

.saas-btn-outline {
  background: transparent;
  border-color: var(--border-line);
  color: var(--text-white);
}

.saas-btn-outline:hover {
  border-color: var(--primary-color);
  background: var(--surface-card);
}

.saas-btn-glass {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border-line);
  color: var(--text-white);
}

.saas-btn-glass:hover {
  background: rgba(255, 255, 255, 0.15);
}

.saas-btn-lg {
  padding: 0.85rem 1.85rem;
  font-size: 1rem;
}

.saas-btn-block {
  width: 100%;
}

.saas-icon-btn {
  background: transparent;
  border: 1px solid var(--border-line);
  color: var(--text-white);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

[data-theme="dark"] .moon-icon { display: none; }
[data-theme="dark"] .sun-icon { display: block; }
[data-theme="light"] .moon-icon { display: block; }
[data-theme="light"] .sun-icon { display: none; }

.saas-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
}

.saas-hamburger span {
  width: 24px;
  height: 2px;
  background: var(--text-white);
}

/* Drawer */
.saas-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background: var(--surface-card);
  box-shadow: 0 0 40px rgba(0,0,0,0.5);
  z-index: 1000;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  transition: right 0.3s ease;
}

.saas-drawer.open {
  right: 0;
}

.saas-drawer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.saas-drawer-close {
  background: none;
  border: none;
  font-size: 2rem;
  color: var(--text-white);
  cursor: pointer;
}

.saas-drawer-links {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.drawer-a {
  color: var(--text-white);
  text-decoration: none;
  font-size: 1.1rem;
  font-weight: 600;
}

/* Hero */
.saas-hero {
  position: relative;
  padding: 5rem 0 4rem;
  overflow: hidden;
}

.saas-glow-bg {
  position: absolute;
  top: -150px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 600px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.22) 0%, rgba(6, 182, 212, 0.08) 50%, transparent 70%);
  pointer-events: none;
}

.hero-center {
  text-align: center;
  max-width: 900px;
  margin: 0 auto;
}

.saas-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(99, 102, 241, 0.15);
  border: 1px solid rgba(99, 102, 241, 0.4);
  color: #a5b4fc;
  padding: 0.4rem 1.1rem;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 1.75rem;
}

.saas-h1 {
  font-size: clamp(2.5rem, 5vw, 4.2rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 1.5rem;
}

.saas-sub {
  font-size: 1.2rem;
  color: var(--text-dim);
  line-height: 1.7;
  max-width: 720px;
  margin: 0 auto 2.5rem;
}

.hero-actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.credit-card-note {
  font-size: 0.85rem;
  color: var(--text-dim);
  margin-bottom: 3.5rem;
}

/* Terminal Showcase */
.hero-showcase {
  background: #0b0f17;
  border: 1px solid var(--border-line);
  border-radius: var(--radius-card);
  overflow: hidden;
  box-shadow: 0 25px 60px rgba(0,0,0,0.6);
  text-align: left;
}

.showcase-header {
  background: #080c14;
  border-bottom: 1px solid var(--border-line);
  padding: 0.75rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mac-dots {
  display: flex;
  gap: 6px;
}

.mac-dots .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.dot.red { background: #ef4444; }
.dot.yellow { background: #f59e0b; }
.dot.green { background: #10b981; }

.tab-list {
  display: flex;
  gap: 0.5rem;
}

.tab-item {
  background: none;
  border: none;
  font-family: var(--saas-mono);
  font-size: 0.8rem;
  color: var(--text-dim);
  padding: 0.3rem 0.75rem;
  border-radius: 4px;
  cursor: pointer;
  transition: var(--transition);
}

.tab-item.active {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-white);
}

.runtime-badge {
  font-family: var(--saas-mono);
  font-size: 0.75rem;
  color: var(--accent-cyan);
}

.showcase-code {
  padding: 1.75rem;
  overflow-x: auto;
}

.showcase-code pre {
  font-family: var(--saas-mono);
  font-size: 0.95rem;
  line-height: 1.7;
}

.c-keyword { color: #f43f5e; font-weight: bold; }
.c-str { color: #34d399; }
.c-comment { color: #64748b; font-style: italic; }
.c-num { color: #38bdf8; }

/* Logos */
.saas-logos {
  padding: 3rem 0;
  border-top: 1px solid var(--border-line);
  border-bottom: 1px solid var(--border-line);
  text-align: center;
}

.logos-caption {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-dim);
  margin-bottom: 1.5rem;
}

.logo-strip {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 3.5rem;
  flex-wrap: wrap;
}

.logo-item {
  font-weight: 800;
  letter-spacing: 0.08em;
  font-size: 1.1rem;
  color: var(--text-dim);
  opacity: 0.7;
}

.logo-item small {
  color: var(--primary-color);
}

/* Features */
.saas-section {
  padding: 6rem 0;
}

.saas-section-alt {
  background: var(--surface-alt);
}

.saas-sec-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem;
}

.saas-tag {
  display: inline-block;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--accent-cyan);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 0.5rem;
}

.saas-sec-title {
  font-size: clamp(2rem, 3.5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 0.75rem;
}

.saas-sec-sub {
  color: var(--text-dim);
  font-size: 1.1rem;
}

.saas-features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: var(--surface-card);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-card);
  padding: 2.5rem;
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-4px);
  border-color: var(--primary-color);
  box-shadow: 0 12px 30px rgba(0,0,0,0.3);
}

.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(99, 102, 241, 0.15);
  color: var(--primary-color);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.feature-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.feature-desc {
  color: var(--text-dim);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* Pricing */
.billing-toggle-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3.5rem;
}

.billing-label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-dim);
}

.billing-switch {
  width: 52px;
  height: 28px;
  background: var(--border-line);
  border-radius: var(--radius-pill);
  border: none;
  cursor: pointer;
  position: relative;
  transition: var(--transition);
}

.billing-switch[aria-checked="true"] {
  background: var(--primary-color);
}

.switch-knob {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #ffffff;
  transition: transform 0.2s ease;
}

.billing-switch[aria-checked="true"] .switch-knob {
  transform: translateX(24px);
}

.discount-tag {
  background: rgba(16, 185, 129, 0.15);
  color: #10b981;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-pill);
  margin-left: 0.3rem;
}

.pricing-cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
  align-items: stretch;
}

.price-card {
  background: var(--surface-card);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-card);
  padding: 3rem 2.5rem;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: var(--transition);
}

.price-card.popular {
  border-color: var(--primary-color);
  box-shadow: 0 0 35px var(--primary-glow);
}

.popular-ribbon {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary-color);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.3rem 0.85rem;
  border-radius: var(--radius-pill);
}

.card-tier {
  font-size: 1.35rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.tier-desc {
  font-size: 0.9rem;
  color: var(--text-dim);
  margin-bottom: 2rem;
  min-height: 42px;
}

.price-val {
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
  margin-bottom: 2rem;
}

.currency {
  font-size: 1.5rem;
  font-weight: 700;
}

.amount {
  font-size: 3.2rem;
  font-weight: 800;
  line-height: 1;
}

.period {
  color: var(--text-dim);
  font-size: 0.9rem;
}

.tier-perks {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 2.5rem;
  flex-grow: 1;
  font-size: 0.9rem;
}

.tier-perks li::before {
  content: "✓ ";
  color: var(--accent-cyan);
  font-weight: bold;
}

/* Accordion */
.saas-accordion {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.saas-acc-item {
  border: 1px solid var(--border-line);
  border-radius: 12px;
  background: var(--surface-card);
  overflow: hidden;
}

.saas-acc-trigger {
  width: 100%;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-white);
  text-align: left;
}

.acc-arrow {
  font-size: 1.4rem;
  color: var(--primary-color);
  transition: transform 0.25s ease;
}

.saas-acc-item.active .acc-arrow {
  transform: rotate(45deg);
}

.saas-acc-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  padding: 0 1.5rem;
  color: var(--text-dim);
}

.saas-acc-item.active .saas-acc-panel {
  padding-bottom: 1.25rem;
}

/* CTA */
.saas-section-cta {
  background: linear-gradient(180deg, var(--bg-dark) 0%, #0c111e 100%);
}

.saas-cta-card {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.12) 0%, rgba(6, 182, 212, 0.08) 100%);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-card);
  padding: 4rem 2rem;
  text-align: center;
}

.saas-cta-card h2 {
  font-size: 2.2rem;
  font-weight: 800;
  margin-bottom: 0.75rem;
}

.saas-cta-card p {
  color: var(--text-dim);
  font-size: 1.1rem;
  margin-bottom: 2rem;
}

.lead-form {
  max-width: 500px;
  margin: 0 auto;
}

.lead-input-wrap {
  display: flex;
  gap: 0.5rem;
}

.lead-input {
  flex: 1;
  padding: 0.85rem 1.25rem;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border-line);
  background: var(--surface-card);
  color: var(--text-white);
  font-family: inherit;
  font-size: 0.95rem;
}

.lead-input:focus {
  outline: none;
  border-color: var(--primary-color);
}

.lead-err {
  display: none;
  font-size: 0.8rem;
  color: #ef4444;
  margin-top: 0.5rem;
  text-align: left;
}

.lead-form.has-error .lead-err {
  display: block;
}

/* Footer */
.saas-footer {
  border-top: 1px solid var(--border-line);
  padding: 4rem 0 2rem;
}

.footer-flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.f-info p {
  color: var(--text-dim);
  font-size: 0.9rem;
  margin-top: 0.5rem;
  max-width: 320px;
}

.f-links {
  display: flex;
  gap: 1.5rem;
}

.f-links a {
  color: var(--text-dim);
  text-decoration: none;
  font-size: 0.9rem;
}

.f-links a:hover {
  color: var(--primary-color);
}

.footer-copy {
  border-top: 1px solid var(--border-line);
  padding-top: 2rem;
  font-size: 0.85rem;
  color: var(--text-dim);
}

/* Modal */
.saas-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(6px);
  z-index: 1000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.saas-modal-backdrop.open {
  display: flex;
}

.saas-modal-box {
  background: var(--surface-card);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-card);
  max-width: 440px;
  width: 100%;
  padding: 2.5rem;
}

.modal-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}

.modal-x {
  background: none;
  border: none;
  color: var(--text-dim);
  font-size: 1.8rem;
  cursor: pointer;
}

.input-field {
  margin-bottom: 1.25rem;
}

.input-field label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.saas-input {
  width: 100%;
  padding: 0.8rem 1rem;
  background: var(--bg-dark);
  border: 1px solid var(--border-line);
  color: var(--text-white);
  border-radius: var(--radius-input);
  font-family: inherit;
}

.saas-input:focus {
  outline: none;
  border-color: var(--primary-color);
}

/* Toast */
.saas-toast-box {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 2000;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.saas-toast {
  background: var(--surface-card);
  border: 1px solid var(--primary-color);
  color: var(--text-white);
  padding: 0.9rem 1.4rem;
  border-radius: var(--radius-input);
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 768px) {
  .saas-nav { display: none; }
  .saas-hamburger { display: flex; }
  .lead-input-wrap { flex-direction: column; }
  .saas-btn-block { width: 100%; }
}

