// OmniFlow AI - Interactive Terminal & Pricing Engine
document.addEventListener('DOMContentLoaded', () => {
  // Theme Toggle
  const themeToggle = document.getElementById('themeToggleBtn');
  const storedTheme = localStorage.getItem('saasTheme') || 'dark';
  document.documentElement.setAttribute('data-theme', storedTheme);

  themeToggle?.addEventListener('click', () => {
    const cur = document.documentElement.getAttribute('data-theme');
    const next = cur === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('saasTheme', next);
  });

  // Mobile Drawer
  const mobileToggle = document.getElementById('mobileMenuToggle');
  const drawer = document.getElementById('mobileDrawer');
  const closeDrawer = document.getElementById('closeDrawerBtn');

  mobileToggle?.addEventListener('click', () => drawer?.classList.add('open'));
  closeDrawer?.addEventListener('click', () => drawer?.classList.remove('open'));
  document.querySelectorAll('.drawer-a').forEach(link => {
    link.addEventListener('click', () => drawer?.classList.remove('open'));
  });

  // Code Tab Switcher
  const tabs = document.querySelectorAll('.tab-item');
  const codeDisplay = document.getElementById('codeDisplay');

  const codeSnippets = {
    stream: `<span class="c-keyword">import</span> omniflow <span class="c-keyword">as</span> of

<span class="c-comment"># Declare autonomous streaming pipeline with self-healing schema</span>
pipeline = of.Pipeline(
    source=of.PostgresCDC(host=<span class="c-str">"db.internal.corp"</span>, slot=<span class="c-str">"production_cdc"</span>),
    sink=of.SnowflakeVector(warehouse=<span class="c-str">"ANALYTICS_WH"</span>, embeddings=<span class="c-str">"text-embedding-3-large"</span>),
    drift_policy=of.Policy.AUTONOMOUS_RESOLVE,
    latency_target_ms=<span class="c-num">85</span>
)

<span class="c-comment"># Engine streams 120k events/sec with zero memory leaks</span>
pipeline.start_autonomous_stream()`,

    schema: `<span class="c-comment"># drift_guard.py - Automated AST validation on incoming schema diffs</span>
<span class="c-keyword">def</span> <span class="c-num">handle_schema_drift</span>(event_payload):
    diff = of.detect_type_variance(event_payload)
    <span class="c-keyword">if</span> diff.has_new_column:
        migration = of.generate_ddl(diff, target=<span class="c-str">"snowflake"</span>)
        migration.apply_instant_shadow_branch()
        <span class="c-keyword">return</span> of.STATUS_HEALED_OK`,

    vector: `<span class="c-comment">-- vector_sync.sql - Real-time continuous embedding generation</span>
CREATE CONTINUOUS VECTOR STREAM raw_customer_feedback_idx
AS SELECT
  customer_id,
  timestamp,
  omni_vectorize(feedback_text, model => 'text-embedding-3-large') AS embedding_vector
FROM cdc_support_tickets_stream
WATERMARK FOR timestamp BOUNDED BY INTERVAL '2' SECOND;`
  };

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      const key = tab.getAttribute('data-tab');
      if (codeDisplay && codeSnippets[key]) {
        codeDisplay.innerHTML = codeSnippets[key];
      }
    });
  });

  // Billing Toggle (Monthly vs Annual -20%)
  const billingSwitch = document.getElementById('billingSwitch');
  const priceDev = document.getElementById('priceDev');
  const priceGrowth = document.getElementById('priceGrowth');
  const priceEnt = document.getElementById('priceEnt');
  let isAnnual = false;

  billingSwitch?.addEventListener('click', () => {
    isAnnual = !isAnnual;
    billingSwitch.setAttribute('aria-checked', String(isAnnual));

    if (isAnnual) {
      if (priceGrowth) priceGrowth.textContent = '79';
      if (priceEnt) priceEnt.textContent = '319';
    } else {
      if (priceGrowth) priceGrowth.textContent = '99';
      if (priceEnt) priceEnt.textContent = '399';
    }
  });

  // FAQ Accordions
  const accItems = document.querySelectorAll('.saas-acc-item');
  accItems.forEach(item => {
    const trigger = item.querySelector('.saas-acc-trigger');
    const panel = item.querySelector('.saas-acc-panel');

    trigger?.addEventListener('click', () => {
      const isOpen = item.classList.contains('active');
      accItems.forEach(i => {
        i.classList.remove('active');
        const p = i.querySelector('.saas-acc-panel');
        if (p) p.style.maxHeight = null;
      });

      if (!isOpen) {
        item.classList.add('active');
        if (panel) panel.style.maxHeight = panel.scrollHeight + 20 + 'px';
      }
    });
  });

  // Toast Functionality
  function triggerSaasToast(msg) {
    const box = document.getElementById('toastBox');
    if (!box) return;
    const toast = document.createElement('div');
    toast.className = 'saas-toast';
    toast.textContent = '⚡ ' + msg;
    box.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);
  }

  // Auth Modal
  const authModal = document.getElementById('authModal');
  const openAuthBtns = [
    document.getElementById('loginModalBtn'),
    document.getElementById('getStartedBtn'),
    document.getElementById('heroTrialBtn'),
    document.getElementById('drawerTrialBtn'),
    document.getElementById('btnDevTier'),
    document.getElementById('btnGrowthTier'),
    document.getElementById('btnEntTier')
  ];
  const closeAuthModal = document.getElementById('closeAuthModal');

  openAuthBtns.forEach(btn => {
    btn?.addEventListener('click', () => authModal?.classList.add('open'));
  });

  closeAuthModal?.addEventListener('click', () => authModal?.classList.remove('open'));
  window.addEventListener('click', (e) => {
    if (e.target === authModal) authModal?.classList.remove('open');
  });

  const signInForm = document.getElementById('signInForm');
  signInForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    authModal?.classList.remove('open');
    triggerSaasToast('Welcome back! Initializing workspace session.');
    signInForm.reset();
  });

  // Demo Video Simulation
  const heroDemoBtn = document.getElementById('heroDemoBtn');
  heroDemoBtn?.addEventListener('click', () => {
    triggerSaasToast('Live interactive sandbox spinning up on Kubernetes...');
  });

  // Lead Capture Form
  const leadForm = document.getElementById('saasLeadForm');
  leadForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    const emailInput = document.getElementById('leadEmail');
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailRegex.test(emailInput.value.trim())) {
      leadForm.classList.add('has-error');
    } else {
      leadForm.classList.remove('has-error');
      triggerSaasToast('Instant sandbox credentials dispatched to ' + emailInput.value);
      leadForm.reset();
    }
  });
});

css:
/* Vanguard Precision Dynamics - High-End Industrial Styling */
:root {
  --ind-font: 'Plus Jakarta Sans', sans-serif;
  --ind-mono: 'Space Grotesk', monospace;

  --bg-color: #0b0f19;
  --surface-color: #111827;
  --surface-alt: #1f2937;
  --border-color: #374151;
  --border-accent: #f59e0b;

  --primary-accent: #f59e0b;
  --primary-hover: #d97706;
  --primary-glow: rgba(245, 158, 11, 0.25);

  --text-main: #f9fafb;
  --text-muted: #9ca3af;
  --text-dim: #6b7280;

  --green-accent: #10b981;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;

  --transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-theme="light"] {
  --bg-color: #f3f4f6;
  --surface-color: #ffffff;
  --surface-alt: #e5e7eb;
  --border-color: #d1d5db;
  --border-accent: #d97706;

  --primary-accent: #d97706;
  --primary-hover: #b45309;
  --primary-glow: rgba(217, 119, 6, 0.2);

  --text-main: #111827;
  --text-muted: #4b5563;
  --text-dim: #9ca3af;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--ind-font);
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.ind-container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.max-w-narrow {
  max-width: 820px;
}

/* Industrial Header */
.ind-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(17, 24, 39, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

[data-theme="light"] .ind-header {
  background: rgba(255, 255, 255, 0.92);
}

.ind-nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 74px;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.ind-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: var(--text-main);
}

.ind-brand-badge {
  background: var(--primary-accent);
  color: #000;
  font-family: var(--ind-mono);
  font-weight: 800;
  font-size: 0.85rem;
  padding: 0.25rem 0.6rem;
  border-radius: var(--radius-sm);
  letter-spacing: 0.05em;
}

.ind-brand-title {
  font-size: 1.25rem;
  letter-spacing: -0.02em;
}

.ind-brand-title strong {
  color: var(--primary-accent);
}

.ind-nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.ind-nav-link {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 600;
  transition: var(--transition);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.ind-nav-link:hover {
  color: var(--primary-accent);
}

.ind-nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.ind-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--ind-mono);
  font-weight: 700;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.7rem 1.4rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: 1px solid transparent;
  transition: var(--transition);
  text-decoration: none;
}

.ind-btn-primary {
  background: var(--primary-accent);
  color: #000000;
}

.ind-btn-primary:hover {
  background: var(--primary-hover);
  box-shadow: 0 0 18px var(--primary-glow);
  transform: translateY(-2px);
}

.ind-btn-secondary {
  background: transparent;
  border-color: var(--border-color);
  color: var(--text-main);
}

.ind-btn-secondary:hover {
  border-color: var(--primary-accent);
  background: var(--surface-alt);
}

.ind-btn-lg {
  padding: 0.9rem 2rem;
  font-size: 0.95rem;
}

.ind-btn-block {
  width: 100%;
}

.ind-icon-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-main);
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.ind-icon-btn:hover {
  border-color: var(--primary-accent);
}

[data-theme="dark"] .moon-icon { display: none; }
[data-theme="dark"] .sun-icon { display: block; }
[data-theme="light"] .moon-icon { display: block; }
[data-theme="light"] .sun-icon { display: none; }

.ind-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
}

.ind-hamburger span {
  width: 24px;
  height: 2px;
  background: var(--text-main);
}

/* Mobile Drawer */
.ind-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 320px;
  height: 100vh;
  background: var(--surface-color);
  border-left: 1px solid var(--border-color);
  z-index: 1000;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  transition: right 0.35s ease;
}

.ind-drawer.open {
  right: 0;
}

.drawer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.drawer-close {
  background: none;
  border: none;
  color: var(--text-main);
  font-size: 2rem;
  cursor: pointer;
}

.drawer-menu {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.drawer-item {
  color: var(--text-main);
  text-decoration: none;
  font-family: var(--ind-mono);
  font-weight: 600;
  font-size: 1.1rem;
}

/* Hero Section */
.ind-hero {
  position: relative;
  padding: 5rem 0 4rem;
  background: radial-gradient(circle at 80% 20%, rgba(245, 158, 11, 0.08) 0%, transparent 60%);
  border-bottom: 1px solid var(--border-color);
}

.ind-grid-overlay {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(var(--border-color) 1px, transparent 1px),
                    linear-gradient(90deg, var(--border-color) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.15;
  pointer-events: none;
}

.hero-flex {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  align-items: center;
  gap: 3.5rem;
  position: relative;
}

.ind-tag-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid var(--primary-accent);
  color: var(--primary-accent);
  font-family: var(--ind-mono);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-sm);
  margin-bottom: 1.5rem;
}

.ind-hero-h1 {
  font-size: clamp(2.2rem, 4vw, 3.6rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 1.25rem;
}

.ind-hero-p {
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 2.25rem;
  max-width: 580px;
}

.ind-cta-row {
  display: flex;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}

.cert-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.cert-pill {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  font-family: var(--ind-mono);
  font-size: 0.75rem;
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
}

/* Hero Machine Card */
.machine-view-card {
  position: relative;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.35);
}

.machine-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  display: block;
}

.telemetry-box {
  position: absolute;
  background: rgba(17, 24, 39, 0.9);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border-color);
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  font-family: var(--ind-mono);
}

.box-tl { top: 16px; left: 16px; }
.box-br { bottom: 16px; right: 16px; }

.tele-label {
  display: block;
  font-size: 0.7rem;
  color: var(--text-dim);
  text-transform: uppercase;
}

.tele-val {
  font-size: 1rem;
  font-weight: 700;
  color: var(--primary-accent);
}

/* Stats Bar */
.ind-stats-bar {
  background: var(--surface-color);
  border-bottom: 1px solid var(--border-color);
  padding: 2.5rem 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-cell {
  border-right: 1px solid var(--border-color);
  padding: 0 1rem;
}

.stat-cell:last-child {
  border-right: none;
}

.stat-big {
  display: block;
  font-family: var(--ind-mono);
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--primary-accent);
  line-height: 1.1;
}

.stat-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* Sections */
.ind-section {
  padding: 6rem 0;
}

.ind-section-alt {
  background-color: var(--surface-color);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

.ind-section-darker {
  background-color: #080c14;
}

.ind-section-head {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem;
}

.ind-sec-tag {
  display: inline-block;
  font-family: var(--ind-mono);
  font-size: 0.8rem;
  color: var(--primary-accent);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 0.5rem;
}

.ind-sec-title {
  font-size: clamp(2rem, 3.2vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 0.75rem;
}

.ind-sec-sub {
  color: var(--text-muted);
  font-size: 1.05rem;
}

/* Capabilities Grid */
.cap-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}

.cap-card {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
}

.cap-card:hover {
  border-color: var(--primary-accent);
  transform: translateY(-4px);
}

.cap-img-wrapper {
  aspect-ratio: 16/9;
  overflow: hidden;
}

.cap-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.cap-card:hover .cap-img {
  transform: scale(1.05);
}

.cap-body {
  padding: 2rem;
}

.cap-title {
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.cap-desc {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 1.25rem;
}

.cap-specs {
  list-style: none;
  font-size: 0.85rem;
  color: var(--text-muted);
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.cap-specs li::before {
  content: "▸ ";
  color: var(--primary-accent);
  font-weight: bold;
}

/* Interactive RFQ Estimator */
.ind-calc-container {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  background: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.ind-calc-form {
  padding: 3rem;
}

.ind-form-row {
  display: flex;
  gap: 1.5rem;
}

.ind-group {
  margin-bottom: 1.5rem;
}

.flex-1 { flex: 1; }

.ind-label {
  display: block;
  font-family: var(--ind-mono);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 0.5rem;
}

.ind-highlight {
  color: var(--primary-accent);
}

.ind-select, .ind-input, .ind-textarea {
  width: 100%;
  padding: 0.85rem 1rem;
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  color: var(--text-main);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 0.95rem;
  transition: var(--transition);
}

.ind-select:focus, .ind-input:focus, .ind-textarea:focus {
  outline: none;
  border-color: var(--primary-accent);
}

.ind-range {
  width: 100%;
  accent-color: var(--primary-accent);
  margin-top: 0.5rem;
}

.ind-checkbox-row {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-top: 0.5rem;
}

.ind-chk-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
  color: var(--text-muted);
  cursor: pointer;
}

.ind-calc-output {
  background: var(--surface-alt);
  padding: 3rem;
  border-left: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.output-title {
  font-family: var(--ind-mono);
  font-size: 1rem;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  color: var(--text-main);
}

.output-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--border-color);
}

.output-key {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.output-val {
  font-family: var(--ind-mono);
  font-weight: 700;
  font-size: 1.25rem;
}

.text-green {
  color: var(--green-accent);
}

.ind-mt-2 {
  margin-top: 1.5rem;
}

/* QA Boxes */
.qa-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.qa-box {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 2.5rem;
  position: relative;
}

.qa-num {
  font-family: var(--ind-mono);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--border-color);
  line-height: 1;
  margin-bottom: 1rem;
}

.qa-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.qa-text {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* RFQ Form */
.rfq-wrapper {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 3.5rem;
}

.rfq-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.rfq-header h2 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.rfq-header p {
  color: var(--text-muted);
}

.ind-err {
  display: none;
  font-size: 0.8rem;
  color: #ef4444;
  margin-top: 0.3rem;
}

.ind-group.has-error .ind-err {
  display: block;
}

.ind-group.has-error .ind-input {
  border-color: #ef4444;
}

/* Footer */
.ind-footer {
  background: #080c14;
  border-top: 1px solid var(--border-color);
  padding: 4.5rem 0 2rem;
}

.footer-cols {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3.5rem;
}

.f-desc {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin: 1rem 0;
  max-width: 340px;
}

.cage-tag {
  display: inline-block;
  font-family: var(--ind-mono);
  font-size: 0.75rem;
  color: var(--primary-accent);
  border: 1px dashed var(--primary-accent);
  padding: 0.35rem 0.65rem;
}

.f-col h4 {
  font-family: var(--ind-mono);
  font-size: 0.95rem;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}

.f-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.f-col li {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.sub-footer {
  border-top: 1px solid var(--border-color);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
  color: var(--text-dim);
  flex-wrap: wrap;
  gap: 1rem;
}

.sub-links {
  display: flex;
  gap: 1.5rem;
}

.sub-links a {
  color: var(--text-muted);
  text-decoration: none;
}

.sub-links a:hover {
  color: var(--primary-accent);
}

/* Modal */
.ind-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.ind-modal-backdrop.open {
  display: flex;
}

.ind-modal-box {
  background: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  max-width: 500px;
  width: 100%;
  padding: 2.5rem;
}

.modal-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.75rem;
}

.modal-close-x {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 1.8rem;
  cursor: pointer;
}

.modal-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

/* Toast */
.ind-toast-hub {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 2000;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.ind-toast {
  background: var(--surface-color);
  border: 1px solid var(--primary-accent);
  color: var(--text-main);
  padding: 1rem 1.5rem;
  border-radius: var(--radius-sm);
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  font-family: var(--ind-mono);
  font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 992px) {
  .hero-flex {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .ind-hero-p {
    margin: 0 auto 2.25rem;
  }
  .ind-cta-row, .cert-row {
    justify-content: center;
  }
  .ind-calc-container {
    grid-template-columns: 1fr;
  }
  .ind-calc-output {
    border-left: none;
    border-top: 1px solid var(--border-color);
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .stat-cell:nth-child(2) {
    border-right: none;
  }
  .footer-cols {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .ind-nav {
    display: none;
  }
  .ind-hamburger {
    display: flex;
  }
  .ind-form-row {
    flex-direction: column;
    gap: 0;
  }
  .stats-grid {
    grid-template-columns: 1fr;
  }
  .stat-cell {
    border-right: none;
    border-bottom: 1px solid var(--border-color);
    padding: 1rem 0;
  }
  .footer-cols {
    grid-template-columns: 1fr;
  }
}

